import * as THREE from 'three';
import { Text, getSelectionRects } from 'troika-three-text'

import gsap from "gsap"
import { debugLog } from "../../../debugger/debugLog.js";
import { COLORS } from '../../../siteData.js';

export default async function section4Back(animManager) {

    debugLog("Section 3", "sec4_debug");


    const sectionDuration = 5;
    const butterflyPath = "paths/butterflySec4.json";
    const snakePath = "paths/snakeSec4.json";

    animManager.section4BackTl = gsap.timeline({ paused: animManager.typeSectional })

    const phasingData = { progress: 0 };

    // moon 
    animManager.section4BackTl
        .to(phasingData, {
            progress: sectionDuration, // Animate from 0 to 1
            duration: sectionDuration,
            // ease: "power1.inOut",
            onStart: () => {
                debugLog("showing work nav", "about_nav_bug2");

                animManager.workRightNav.iconMesh.layers.set(0);
                animManager.workLeftNav.iconMesh.layers.set(0);
                animManager.workLeftNav.layers.set(0);
                animManager.workRightNav.layers.set(0);

            },
            onUpdate: () => {
                animManager.moonMaterial.uniforms.uTime.value = animManager.moonPhasingData.progress - phasingData.progress; // One full rotation for the phase cycle            
            },
            onComplete: () => {
                debugLog("moon completed section 3 ", "sec3_debug");
                animManager.moonPhasingData.progress = animManager.moonPhasingData.progress - phasingData.progress;
            }
        }, 0);
    const butterflyCurveId = await animManager.curveEditor.loadCurveFromPath(butterflyPath, "bfly-sec4-bck");
    const butterflyCurve1 = animManager.curveEditor.curves[butterflyCurveId].curve3;

    const butterflyFlightData = { progress: 1 };
    animManager.section4BackTl.to(butterflyFlightData, {
        progress: 0,
        duration: sectionDuration - 2,
        ease: "sine.in",
        onUpdate: () => {
            if (butterflyFlightData.progress < 0)
                return;
            let position = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress, 0, 0);
            animManager.butterfly.position.copy(position);
            if (butterflyFlightData.progress + 0.01 < 1) {
                let lookAtPosition = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress + 0.01, 0, 0);
                animManager.butterfly.lookAt(lookAtPosition);
            }
            const snakePos = position.add(animManager.bgMeshOffest);
            animManager.snake.update(snakePos, butterflyFlightData.progress);
        }
    }, 0);

    debugLog("Section 4 animManager.workRightNav.iconMesh is null " + (animManager.workRightNav.iconMesh == null), "sec4_debug");

    animManager.section4BackTl.to(animManager.workTextUniforms.uDissolve, { value: 0, duration: sectionDuration, ease: "none" }, 0);
    animManager.section4BackTl.to(animManager.workTitleUniforms.uDissolve, { value: 0, duration: sectionDuration, ease: "none" }, 0);
    animManager.section4BackTl.to(animManager.workBase.material, { opacity: 1.0, duration: sectionDuration, ease: "none" }, 0);
    animManager.section4BackTl.to(animManager.workRightNav.iconMesh.material, { opacity: 1.0, duration: sectionDuration, ease: "none" }, 0);
    animManager.section4BackTl.to(animManager.workLeftNav.iconMesh.material, { opacity: 1.0, duration: sectionDuration, ease: "none" }, 0);
    animManager.section4BackTl.to(animManager.projectBase.material, { opacity: 1.0, duration: sectionDuration, ease: "none" }, 0);
    animManager.section4BackTl.to(animManager.projectTitleUnderline.material, {
        linewidth: 1, duration: sectionDuration, ease: "expo.inOut",
        onUpdate: () => {
            animManager.aboutUnderline.material.needsUpdate = true;
        },
    }, 0);
    animManager.section4BackTl.to(animManager.projectIcon.material, {
        opacity: 1.0, duration: sectionDuration, ease: "none",
        onUpdate: () => {
            animManager.projectIcon.material.needsUpdate = true;
        },
    }, 0);

    animManager.section4BackTl.call(() => {
        debugLog("morph to snake", "tl_rev");
        animManager.projectTechStackMeshes.forEach((mesh, tech) => {
            animManager.section4BackTl.to(mesh.material, { opacity: 1.0, duration: sectionDuration, ease: "none" }, 0);

        });
    }, [], 0);


    animManager.section4BackTl.to(animManager.testimonialGroup.position, { y: animManager.testimonialSec4StartPosY, duration: sectionDuration, ease: 'power2.inOut' }, 0);

    animManager.section4BackTl.to(animManager.grassMesh.grassUniforms.opacity, {
        value: 0, duration: 1, ease: "none",
        onComplete: () => {
            animManager.disableGrass();
        }
    }, "<");

    // Whenever you are ready to reveal the stars (e.g., after a loading screen or on scroll):
    animManager.section4BackTl.to(animManager.backdrop.material.uniforms.uOpacity, {
        value: 0,         // Target fully visible
        duration: 1,        // Over 3 seconds
        ease: "power2.out",
        onComplete: () => {
            animManager.backdrop.visible = false;
            animManager.animateBackdrop = false;
        }
    }, "<");

    animManager.section4BackTl.to(animManager.litBG.material, {
        opacity: 0.0,
        duration: 1,        // Over 3 seconds
        ease: "power2.inOut"
    }, "<");

    // animation.section4BackTl.to(
    // return "test";
    debugLog("Section 4 end", "sec4_debug");
    // return tl;
}