const textDissolveFragNoise = `
  #include <common>
  
  uniform float uDissolve;
  uniform float uEdgeWidth;
  uniform vec3 uEdgeColor;
  uniform float uNoiseScale;
  uniform vec3 uTextColor;
  
  // Pseudo-random hash function
  float hash(vec2 p) {
      return fract(1e4 * sin(17.0 * p.x + p.y * 0.1) * (0.1 + abs(sin(p.y * 13.0 + p.x))));
  }
  
  // Smooth 2D Value Noise
  float noise(vec2 x) {
      vec2 i = floor(x);
      vec2 f = fract(x);
      
      // Four corners of a 2D square
      float a = hash(i);
      float b = hash(i + vec2(1.0, 0.0));
      float c = hash(i + vec2(0.0, 1.0));
      float d = hash(i + vec2(1.0, 1.0));
      
      // Smooth interpolation
      vec2 u = f * f * (3.0 - 2.0 * f);
      
      // Mix it all together
      return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
  }`;

const testDissolveFragShader = `
  #include <dithering_fragment>
  
  // Use our new smooth noise function instead of the static random one
  // We stretch it slightly on the Y axis for a more "flame-like" upward burn
  float n = noise(vec2(vUv.x * uNoiseScale, vUv.y * uNoiseScale * 1.5)); 
  
  if (n < uDissolve) {
      discard;
  }
  
  gl_FragColor.rgb = uTextColor;
  
  if (n < uDissolve + uEdgeWidth) {
      float edgeFactor = smoothstep(uDissolve, uDissolve + uEdgeWidth, n);
      gl_FragColor.rgb = mix(uEdgeColor, gl_FragColor.rgb, edgeFactor);
  }`;

