  //#region Curves and Positions Helpers

  getResponsivePoint(curve, progress, xOffset = 0, yOffset = 0) {
    const pt = curve.getPoint(progress);

    // Apply scale and offsets
    pt.x = (pt.x * this.scaleFactorVec.x) + xOffset;
    pt.y = (pt.y * this.scaleFactorVec.y) + yOffset;
    pt.z = pt.z; // Don't forget to scale depth so the flight arc looks natural!

    return pt;
  }

  createPathCurveFromPositions(positions, scene, visualDebug = false, debugCurve = null) {

    const newCurve = new THREE.CatmullRomCurve3(positions);
    newCurve.closed = false;

    if (visualDebug) {
      positions.forEach(pos => {
        const dotGeo = new THREE.SphereGeometry(10, 16, 16);
        const dotMat = new THREE.MeshBasicMaterial({ color: 0xff0000 });
        const dotMesh = new THREE.Mesh(dotGeo, dotMat);
        dotMesh.position.copy(pos);
        scene.add(dotMesh); // Add to scene directly to ignore scrolling
      });
      if (!debugCurve) {
        // Visual Debugging: Create a visible line to see the path (remove in production)
        const curvePoints = newCurve.getPoints(50);

        // const geometry = new THREE.BufferGeometry().setFromPoints(curvePoints);
        // const material = new THREE.LineBasicMaterial({ color: Math.floor(Math.random() * 0xffffff) });
        // debugCurve = new THREE.Line(geometry, material);


        const geometry = new LineGeometry();
        const positions = [];
        curvePoints.forEach(p => {
          positions.push(p.x, p.y, p.z);

        });
        geometry.setPositions(positions);

        const material = new LineMaterial({
          color: Math.floor(Math.random() * 0xffffff),
          linewidth: 12, // in pixels
          worldUnits: false,
        });
        material.resolution.set(window.innerWidth, window.innerHeight); // important!

        debugCurve = new Line2(geometry, material);

        scene.add(debugCurve);
      }
      else {
        // Faster alternative if the point count is identical:
        const positions = debugCurve.geometry.attributes.position.array;
        const newPoints = newCurve.getPoints(50);

        for (let i = 0; i < newPoints.length; i++) {
          positions[i * 3] = newPoints[i].x;
          positions[i * 3 + 1] = newPoints[i].y;
          positions[i * 3 + 2] = newPoints[i].z;
        }

        debugCurve.geometry.attributes.position.needsUpdate = true;
      }
    }

    return newCurve;
  }

  getLetterWorldPosition(textObject, letterIndex) {


    return new Promise((resolve) => {
      //debugLog("3433333333333 " );

      if (textObject.textRenderInfo) {
        const renderInfo = textObject.textRenderInfo;

        const letterRect = getSelectionRects(renderInfo, letterIndex, letterIndex + 1);

        if (!letterRect || letterRect.length === 0) {
          console.error(`Could not get selection rect for index ${letterIndex} in text "${textObject.text}".`);
          resolve(null);
          return;
        }
        // The rect gives us local coordinates for the letter. We'll use its center.
        const rect = letterRect[0];

        // Calculate the center of the character's bounding rectangle
        const centerX = (rect.left + rect.right) / 2;
        const centerY = (rect.top + rect.bottom) / 2;
        const localPosition = new THREE.Vector3(centerX, centerY, 0);
        // Convert the local position to a world position
        resolve(textObject.localToWorld(localPosition.clone()));
      }
      else {

        textObject.sync(() => {
          const renderInfo = textObject.textRenderInfo;
          if (!renderInfo || !renderInfo.glyphs || letterIndex >= renderInfo.glyphs.length) {
            console.error("Could not get glyphs or letter index is out of bounds.");
            resolve(null);
            return;
          }
          const letterRect = getSelectionRects(renderInfo, letterIndex, letterIndex + 1);

          if (!letterRect || letterRect.length === 0) {
            console.error(`Could not get selection rect for index ${letterIndex} in text "${textObject.text}".`);
            resolve(null);
            return;
          }
          // The rect gives us local coordinates for the letter. We'll use its center.
          const rect = letterRect[0];

          // Calculate the center of the character's bounding rectangle
          const centerX = (rect.left + rect.right) / 2;
          const centerY = (rect.top + rect.bottom) / 2;
          const localPosition = new THREE.Vector3(centerX, centerY, 0);
          // Convert the local position to a world position
          resolve(textObject.localToWorld(localPosition.clone()));
        });
      }

    });
  }

