  async setupProjectIconDissolve() {
    const imageMesh = this.projectIcon; //
    if (!imageMesh) return null;

    // Avoid re-creating if already set up
    if (imageMesh.material?.uniforms?.uProgress) {
      return imageMesh.material;
    }

    const currentTexture = imageMesh.material?.map || null;

    const dissolveMat = createImageDissolveMaterial(currentTexture, {
      clippingPlanes: this.uiClipPlanes,
      edgeWidth: 0.2,
      // colorLead: new THREE.Color(0.95 //228.225 , 0.35 //89.25, 0.01 //2.55),
      colorLead: new THREE.Color('#00ffdd'),
      colorTrail: new THREE.Color(COLORS.text),
      // colorTrail: new THREE.Color(0.95  //228.225, 0.75 //191.25, 0.01 //2.55),
    });

    imageMesh.material = dissolveMat;
    imageMesh.material.needsUpdate = true;
    return dissolveMat;
  }

  async triggerProjectIconDissolve(nextTextureOrPath, options = {}) {
    const imageMesh = this.projectIcon;
    if (!imageMesh) return null;

    // Ensure dissolve material is ready on imageMesh
    if (!imageMesh.material?.uniforms?.uProgress) {
      SetupProjectIconDissolve();
    }

    const duration = typeof options === 'number' ? options : (options.duration ?? 1.2);
    const onComplete = typeof options === 'object' ? options.onComplete : undefined;

    // 1. If a path string is provided, load the texture first
    if (typeof nextTextureOrPath === 'string') {
      return loadingController.getTextureLoader().load(nextTextureOrPath, (loadedTex) => {
        loadedTex.colorSpace = THREE.SRGBColorSpace;
        transitionImageDissolve(imageMesh, loadedTex, { duration, onComplete });
      });
    }

    // 2. If a THREE.Texture is provided
    if (nextTextureOrPath && nextTextureOrPath.isTexture) {
      nextTextureOrPath.colorSpace = THREE.SRGBColorSpace;
      return transitionImageDissolve(imageMesh, nextTextureOrPath, { duration, onComplete });
    }

    // 3. If called with no arguments, dissolve to next project's thumbnail
    const nextProjectIndex = (currentProjectIndex + 1) % siteContent.projects.length;
    const nextProjectData = siteContent.projects[nextProjectIndex];
    if (nextProjectData?.thumbnailPath) {
      return loadingController.getTextureLoader().load(nextProjectData.thumbnailPath, (loadedTex) => {
        loadedTex.colorSpace = THREE.SRGBColorSpace;
        transitionImageDissolve(imageMesh, loadedTex, { duration, onComplete });
      });
    }
  }

