  // #region Profiler

  profilerBeginFrame() {

    if (this.profilerSettings && this.profilerSettings.enabled && this.profiler) {
      this.profiler.beginFrame();
    }
  }

  profilerUpdateData() {
    if (this.profilerSettings && this.profilerSettings.enabled && this.profiler) {
      this.profiler.endFrame();
      const data = this.profiler.sample();
      this.profilerSettings.timestamp = data.timestamp;
      this.profilerSettings.fps = data.fps;
      this.profilerSettings.frameTime = data.frameTime;
      this.profilerSettings.frameInterval = data.frameInterval;
      this.profilerSettings.jsHeapUsed = data.jsHeapUsed ? Math.round((data.jsHeapUsed / 1048576) * 100) / 100 : 0;
      this.profilerSettings.jsHeapTotal = data.jsHeapTotal ? Math.round((data.jsHeapTotal / 1048576) * 100) / 100 : 0;
      this.profilerSettings.drawCalls = data.drawCalls;
      this.profilerSettings.triangles = data.triangles;
      this.profilerSettings.lines = data.lines;
      this.profilerSettings.points = data.points;
      this.profilerSettings.geometries = data.geometries;
      this.profilerSettings.textures = data.textures;
      this.profilerSettings.pixelRatio = data.pixelRatio;
      this.profilerSettings.canvasWidth = data.canvasWidth;
      this.profilerSettings.canvasHeight = data.canvasHeight;
    }
  }
