function setupLoadingController() {
  if (!renderer) {
    renderer = new THREE.WebGLRenderer({
      canvas: document.querySelector('#bg'),
      antialias: true,
      alpha: false
    });
    renderer.localClippingEnabled = true;
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  }

  // Initialization
  loadingController = new LoadingController(renderer, () => OnMainLoaded());
  loadingController.resize();

  // Cursor Controller for loading screen
  cursorController = new CursorController(renderer, loadingController.getTextureLoader(), loadingController.beginText);
  cursorController.resize(window.innerWidth, window.innerHeight);

  loadingController.cursorController = cursorController;
  cursorController.setScene("loading", loadingController.camera);
  cursorController.registerClickableObject("loading", loadingController.clickGroup);
}

