function setupMainScene() {
  scene = new THREE.Scene();
  scene.background = new THREE.Color(COLORS.background);

  // Orthographic Camera for pixel-perfect layout
  orthoCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, 1, 1000);
  orthoCamera.position.z = 10;

  // Perspective Camera for 3D view
  perspectiveCamera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 5000);
  perspectiveCamera.position.z = 600;

  activeCamera = perspectiveCamera;

  if (!renderer) {
    renderer = new THREE.WebGLRenderer({
      canvas: document.querySelector('#bg'),
      antialias: true,
      alpha: false
    });
    renderer.localClippingEnabled = true;
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  }

  // Sectional animation manager
  sectionalAnimManager = new SectionalAnimationManager();
  sectionalAnimManager.cursorController = cursorController;

  // Group to hold all scrollable content
  contentGroup = new THREE.Group();
  scene.add(contentGroup);

  // 1. Create the background plane
  bgGeometry = new THREE.PlaneGeometry(bgWidth, bgHeight);
  bgGeometry.translate(0, bgHeight / 2, 0);
  bgMaterial = new THREE.MeshBasicMaterial({
    color: COLORS.content_background,
    side: THREE.DoubleSide,
    transparent: true
  });

  backgroundMesh = new THREE.Mesh(bgGeometry, bgMaterial);
  backgroundMesh.name = "backgroundMesh";
  backgroundMesh.position.z = Z_LAYERS.background;

  // Add background to the group
  contentGroup.add(backgroundMesh);

  // Lit Background Textures
  colorTexture = loadingController.getTextureLoader().load(siteContent.litBGTextures.concrete.color, undefined, onError);
  normalTexture = loadingController.getTextureLoader().load(siteContent.litBGTextures.concrete.normal, undefined, onError);
  roughnessTexture = loadingController.getTextureLoader().load(siteContent.litBGTextures.concrete.roughness, undefined, onError);

  litBgGeometry = new THREE.PlaneGeometry(1000, 1000);
  litBgGeometry.translate(0, 1000 / 2, 0);

  litBgMat = new THREE.MeshStandardMaterial({
    map: colorTexture,
    normalMap: normalTexture,
    roughnessMap: roughnessTexture,
    transparent: true,
    side: THREE.DoubleSide,
    opacity: 0.0,
  });
  litBG = new THREE.Mesh(litBgGeometry, litBgMat);
  litBG.position.z = 0;
  backgroundMesh.add(litBG);

  // Lighting
  ambientLight = new THREE.AmbientLight(0xffffff, 4);
  scene.add(ambientLight);

  dirLight = new THREE.DirectionalLight(0xffffff, 2);
  dirLight.position.set(0, 0, 80);
  scene.add(dirLight);

  // Debug Manager
  debugManager = new DebugManager([], stats, 'h');
}

