// #region --- HELPER FUNCTIONS ---

function updateBGMeshSize(width, height) {
  // Instead of scaling, we'll directly manipulate the geometry's vertices.
  // This is better for performance and avoids issues with non-uniform scaling of children.
  const positions = bgGeometry.attributes.position.array;

  const halfWidth = width / 2;

  // The geometry is a simple plane with 4 vertices.
  // We'll update their X and Y coordinates.
  // The order is: bottom-left, bottom-right, top-left, top-right.
  // Because we translated the geometry up by 0.5 initially, the bottom Y is 0 and top Y is 1 (for a 1x1 plane).

  // Bottom-left vertex
  positions[0] = -halfWidth;
  positions[1] = 0;
  // Bottom-right vertex
  positions[3] = halfWidth;
  positions[4] = 0;
  // Top-left vertex
  positions[6] = -halfWidth;
  positions[7] = height;
  // Top-right vertex
  positions[9] = halfWidth;
  positions[10] = height;

  // Inform three.js that the vertices have been updated.
  bgGeometry.attributes.position.needsUpdate = true;
  bgGeometry.computeBoundingBox();
  bgGeometry.computeBoundingSphere();

  // Reset the scale, as we are now controlling size via geometry.
  backgroundMesh.scale.set(1, 1, 1);

  // The geometry's pivot is at its bottom edge. To keep the plane visually centered
  // where it was before (around Y=0), we need to shift it down by half its new height.
  backgroundMesh.position.y = -height / 2;


  const litPositions = litBgGeometry.attributes.position.array;

  // Bottom-left vertex
  litPositions[0] = -halfWidth;
  litPositions[1] = 0;
  // Bottom-right vertex
  litPositions[3] = halfWidth;
  litPositions[4] = 0;
  // Top-left vertex
  litPositions[6] = -halfWidth;
  litPositions[7] = height;
  // Top-right vertex
  litPositions[9] = halfWidth;
  litPositions[10] = height;

  // Inform three.js that the vertices have been updated.
  litBgGeometry.attributes.position.needsUpdate = true;
  litBgGeometry.computeBoundingBox();
  litBgGeometry.computeBoundingSphere();

  // Reset the scale, as we are now controlling size via geometry.
  litBG.scale.set(1, 1, 1);

  // The geometry's pivot is at its bottom edge. To keep the plane visually centered
  // where it was before (around Y=0), we need to shift it down by half its new height.
  litBG.position.y = 0 / 2;
}

