function setupAnimation() {
  setupEventListeners();

  setupTabLifecycle({
    pauseOnWindowBlur: true, // Set to true if clicking another app should pause; false for tab switch only
    onPause: () => {
      isAppPaused = true;
      if (animFrameId) {
        cancelAnimationFrame(animFrameId);
        animFrameId = null;
      }
    },
    onResume: () => {
      isAppPaused = false;
      // Reset clock delta tracking so delta doesn't spike from the background pause time
      clock.oldTime = performance.now();
      timeAccumulator = 0;
      // Restart render loop
      animFrameId = requestAnimationFrame(animate);
    }
  });

  animate();
}

function setupEventListeners() {
  window.addEventListener('resize', updateLayout);
  window.addEventListener('keydown', (event) => {
    if (window.isContactCardActive)
      return;
    if (event.key === 'c') {
      switchCamera();
    }
  });

  window.addEventListener("unhandledrejection", e => {
    console.error("Unhandled Promise rejection: ", e.reason);
  });
}

// #region --- ANIMATION CORE ---
function animate() {
  if (isAppPaused) return;

  animFrameId = requestAnimationFrame(animate);

  sectionalAnimManager?.profilerBeginFrame();

  const delta = clock.getDelta();
  timeAccumulator += delta;
  const time = clock.getElapsedTime();

  // Only render if enough time has passed
  if (timeAccumulator >= interval) {
    stats.begin();
    // stats.update();
    sectionalAnimManager?.animate(delta);
    quoteCloud?.update(renderer);

    if (pipeline != null) {
      // if(chromaticPass)
      //   chromaticPass.uniforms.uOffset.value = 0.005;

      pipeline.render();

    }
    else if (scene)
      renderer?.render(scene, activeCamera);

    if (contactCardManager) {
      renderer.autoClear = false;
      renderer.clearDepth();
      contactCardManager.render(time);
      renderer.autoClear = true;
    }

    loadingController.update(time); // Pass time in seconds for the shader
    cursorController.update(time); // Update cursor position based on mouse

    if (butterflyMixer) {
      butterflyMixer.update(delta);
    }

    debugAnimate(time);
    stats.end();

    timeAccumulator = timeAccumulator % interval;

    sectionalAnimManager?.profilerUpdateData();
  }
}

