import * as THREE from 'three';
import gsap from 'gsap';
import imageDissolveVert from '../glsl/imageDissolve.vert.glsl';
import imageDissolveFrag from '../glsl/imageDissolve.frag.glsl';

/**
 * Creates a THREE.ShaderMaterial configured for procedural burning dissolve transitions between two textures.
 * Based on https://www.shadertoy.com/view/tt3XWB
 *
 * @param {THREE.Texture} [initialTexture=null] - The starting texture
 * @param {Object} [options={}] - Optional configuration
 * @param {number} [options.edgeWidth=0.2] - Width of the burning ember edge
 * @param {THREE.Color|string} [options.colorLead] - Leading ember color (default: orange vec3(.95, .35, .01))
 * @param {THREE.Color|string} [options.colorTrail] - Trailing ember color (default: gold vec3(.95, .75, .01))
 * @param {THREE.Plane[]} [options.clippingPlanes=[]] - Clipping planes for UI clipping
 * @param {number} [options.opacity=1.0] - Overall material opacity
 * @returns {THREE.ShaderMaterial}
 */
export function createImageDissolveMaterial(initialTexture = null, options = {}) {
  const edgeWidth = options.edgeWidth ?? 0.2;

  let leadColor = options.colorLead ? new THREE.Color(options.colorLead) : new THREE.Color(0.95, 0.35, 0.01);
  let trailColor = options.colorTrail ? new THREE.Color(options.colorTrail) : new THREE.Color(0.95, 0.75, 0.01);

  const uniforms = {
    uTexture1: { value: initialTexture || null },
    uTexture2: { value: initialTexture || null },
    uProgress: { value: 0.0 },
    uEdgeWidth: { value: edgeWidth },
    uColorLead: { value: new THREE.Vector3(leadColor.r, leadColor.g, leadColor.b) },
    uColorTrail: { value: new THREE.Vector3(trailColor.r, trailColor.g, trailColor.b) },
    opacity: { value: options.opacity ?? 1.0 },
  };

  const material = new THREE.ShaderMaterial({
    vertexShader: imageDissolveVert,
    fragmentShader: imageDissolveFrag,
    uniforms: uniforms,
    transparent: true,
    side: THREE.DoubleSide,
    depthWrite: false,
    clipping: true,
    clippingPlanes: options.clippingPlanes || [],
  });

  // Getter/setter for opacity to remain compatible with GSAP tweens targeting material.opacity
  Object.defineProperty(material, 'opacity', {
    get() {
      return uniforms.opacity.value;
    },
    set(val) {
      uniforms.opacity.value = val;
    },
    configurable: true,
  });

  // Getter/setter for map for backward compatibility with standard Three.js materials
  Object.defineProperty(material, 'map', {
    get() {
      return uniforms.uTexture1.value;
    },
    set(val) {
      uniforms.uTexture1.value = val;
      if (!uniforms.uTexture2.value) {
        uniforms.uTexture2.value = val;
      }
    },
    configurable: true,
  });

  return material;
}

/**
 * Triggers a dissolve transition from the current texture to nextTexture on the given mesh or material.
 *
 * @param {THREE.Mesh|THREE.ShaderMaterial} target - Mesh with dissolve material or material itself
 * @param {THREE.Texture} nextTexture - Incoming texture
 * @param {Object} [options={}] - Transition options
 * @param {number} [options.duration=0.8] - Duration of transition in seconds
 * @param {string} [options.ease='power2.inOut'] - GSAP ease
 * @param {Function} [options.onComplete] - Callback on transition completion
 * @param {boolean} [options.disposeOld=false] - Whether to dispose the previous texture when done
 * @returns {gsap.core.Tween|null}
 */
export function transitionImageDissolve(target, nextTexture, options = {}) {
  const mesh = target?.isMesh ? target : null;
  const material = mesh ? mesh.material : target;

  if (!material || !material.uniforms || !material.uniforms.uProgress) {
    console.warn("transitionImageDissolve: Target material does not have dissolve uniforms.");
    if (material && 'map' in material) {
      material.map = nextTexture;
      material.needsUpdate = true;
    }
    return null;
  }

  const duration = options.duration ?? 1.2
  const ease = options.ease ?? 'none';
  const onComplete = options.onComplete;

  // If a transition is already animating on this mesh/material, kill it cleanly
  const activeHolder = mesh || material;
  if (activeHolder._dissolveTween) {
    activeHolder._dissolveTween.kill();
    // Complete the previous jump by making uTexture1 whatever uTexture2 was
    if (material.uniforms.uTexture2.value) {
      material.uniforms.uTexture1.value = material.uniforms.uTexture2.value;
    }
    material.uniforms.uProgress.value = 0.0;
  }

  const currentTexture = material.uniforms.uTexture1.value;

  // If new texture is same as current texture, nothing to dissolve
  if (currentTexture === nextTexture) {
    material.uniforms.uProgress.value = 0.0;
    if (onComplete) onComplete();
    return null;
  }

  material.uniforms.uTexture2.value = nextTexture;
  material.uniforms.uProgress.value = 0.0;

  activeHolder._dissolveTween = gsap.to(material.uniforms.uProgress, {
    value: 1.0,
    duration: duration,
    ease: ease,
    onComplete: () => {
      const oldTex = material.uniforms.uTexture1.value;
      material.uniforms.uTexture1.value = nextTexture;
      material.uniforms.uProgress.value = 0.0;
      activeHolder._dissolveTween = null;

      if (options.disposeOld && oldTex && oldTex !== nextTexture) {
        oldTex.dispose();
      }

      if (onComplete) {
        onComplete();
      }
    }
  });

  return activeHolder._dissolveTween;
}

