import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { DRACOLoader } from 'three/examples/jsm/loaders/DRACOLoader.js';
import { CURSOR_STATES, siteContent, COLORS, FONT_SIZE, MIN_FONT_SIZE, THICK_LINE_WIDTH, Z_LAYERS } from '../siteData.js';
import { debugLog } from '../debugger/debugLog.js';

import gsap from 'gsap';
import { createText, createTexture, createRectTextureButton, getDeviceType } from '../utils.js';
import { debug } from 'three/tsl';


export class LoadingController {
    constructor(renderer, onStartExperience) {
        this.renderer = renderer;
        this.onStartExperience = onStartExperience;
        this.isLoaded = false;
        this.experienceStarted = false;
        this.isFinished = false; // Added flag to manage the render loop

        this.scene = new THREE.Scene();
        this.camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.1, 10);
        this.camera.position.z = 1;

        this.cursorController;

        this.setupTroikaUI();
        this.setupPaperMesh();
        this.setupUI();

        this.raycaster = new THREE.Raycaster();
        this.mouse = new THREE.Vector2();

        this.manager = new THREE.LoadingManager();
        this.initManager();

        this.dracoLoader = new DRACOLoader();
        this.dracoLoader.setDecoderPath('draco/');

        this.startupTextureLoader = new THREE.TextureLoader(this.manager);
        this.startupAudioLoader = new THREE.AudioLoader(this.manager);
        this.startupGltfLoader = new GLTFLoader(this.manager);
        this.startupGltfLoader.setDRACOLoader(this.dracoLoader);

        const ambientLight = new THREE.AmbientLight(0xffffff, 1.5);
        this.scene.add(ambientLight);
        const dirLight = new THREE.DirectionalLight(0xffffff, 2);
        dirLight.position.set(1, 1, 1);
        this.scene.add(dirLight);

        this.bindEvents();
        this.resize();
    }

    setupTroikaUI() {
        this.instructionText = createText(
            '* Use headphones.',
            0.06, 'regular', 'left ', 'center', null, 'middle'
        );
        this.instructionText.position.set(0, 0.3, 0.1);
        // this.scene.add(this.instructionText);


        this.scrollText = createText(
            '* Scroll To Go Through Chapters',
            0.06, 'regular', 'left', 'center', null, 'middle'
        );
        this.scrollText.position.set(0, 0.4, 0.1);
        this.scrollText.sync();
        // this.scene.add(this.scrollText);

        this.loadingText = createText(
            'Loading Assets... 0%',
            0.05, 'regular', 'center', 'center', null, 'middle'
        );
        this.loadingText.position.set(0, 0, 0.1);
        this.scene.add(this.loadingText);

        const barGeo = new THREE.PlaneGeometry(1, 0.015);
        this.progressBarBg = new THREE.Mesh(barGeo, new THREE.MeshBasicMaterial({ color: 0xcccccc }));
        this.progressBarBg.position.set(-0.5, 0, 0);

        this.progressBarFill = new THREE.Mesh(barGeo, new THREE.MeshBasicMaterial({ color: 0x0a0a0a }));
        this.progressBarFill.position.set(-0.5, 0, 0);
        this.progressBarFill.scale.x = 0;
        this.progressBarFill.geometry.translate(0.5, 0, 0);

        this.progressBarGroup = new THREE.Group();
        this.progressBarGroup.position.set(0, -0.2, 0.1);
        this.progressBarGroup.add(this.progressBarBg);
        this.progressBarGroup.add(this.progressBarFill);

        this.scene.add(this.progressBarGroup);

        const desktopNoticeMessage = "BEST EXPERIENCED ON DESKTOP\n\nFor the full experience \n recommend a larger screen.".toUpperCase();
        this.desktopNoticeText = createText(
            desktopNoticeMessage,
            0.034, 'bold', 'center', 'center', null, 'middle'
        );
        this.desktopNoticeText.position.set(0, -0.65, 0.1);
        this.desktopNoticeText.visible = false;
        this.scene.add(this.desktopNoticeText);

        // this.beginText = createText(
        //     'CLICK TO BEGIN',
        //     0.08, 'bold', 'center', 'center', null, 'middle'
        // );
        // this.beginText.position.set(0, -0, 0.1);
        // this.beginText.fillOpacity = 0;
        // this.beginText.sync();
        // this.scene.add(this.beginText);
    }

    setupPaperMesh() {
        const geometry = new THREE.PlaneGeometry(2, 2);

        this.uniforms = {
            uTime: { value: 0 },
            uProgress: { value: 0 }
        };

        const onError = (error) => {
            console.error('A texture failed to load:', error);
            // You could implement fallback logic here
        };

        const colorTexture = this.getTextureLoader(true).load(siteContent.litBGTextures.paper.color, undefined, onError);
        const normalTexture = this.getTextureLoader(true).load(siteContent.litBGTextures.paper.normal, undefined, onError);
        const roughnessTexture = this.getTextureLoader(true).load(siteContent.litBGTextures.paper.roughness, undefined, onError);

        this.material = new THREE.MeshStandardMaterial({
            map: colorTexture,
            normalMap: normalTexture,
            roughnessMap: roughnessTexture,
            color: 0xffffff,
            transparent: true,
            side: THREE.DoubleSide
        });
        this.material.defines = { USE_UV: '' };

        this.mesh = new THREE.Mesh(geometry, this.material);
        this.mesh.position.z = 0;
        this.scene.add(this.mesh);
    }

    setupUI() {
        debugLog("setting up ui", "lc");

        const nextLabel = "textures/Loading/next-chapter.png";
        const prevLabel = "textures/Loading/prev-chapter.png";
        const nextControls = "textures/Loading/next-controls.png";
        const prevControls = "textures/Loading/prev-controls.png";

        const workInProgress = "textures/Loading/wip-icon.png";
        const clickToBegin = "textures/Loading/clickbegin.png";

        this.controlGroup = new THREE.Group();
        this.previousGroup = new THREE.Group();
        this.nextGroup = new THREE.Group();

        this.nextLabelMesh = createTexture(this.getTextureLoader(true), nextLabel, 0.441, 0.064);
        this.prevLabelMesh = createTexture(this.getTextureLoader(true), prevLabel, 0.505, 0.116);

        this.nextControlsMesh = createTexture(this.getTextureLoader(true), nextControls, 0.385, 0.235);
        this.prevControlsMesh = createTexture(this.getTextureLoader(true), prevControls, 0.385, 0.235);

        this.workInProgressMesh = createTexture(this.getTextureLoader(true), workInProgress, 0.337, 0.244);
        [this.clickGroup, this.clickMat, this.clickMesh] = createRectTextureButton(this.getTextureLoader(true), clickToBegin, .762, 0.134);
        this.clickGroup.scale.set(0, 0, 1);

        this.nextGroup.add(this.nextLabelMesh);
        this.nextGroup.add(this.nextControlsMesh);

        this.previousGroup.add(this.prevLabelMesh);
        this.previousGroup.add(this.prevControlsMesh);

        this.controlGroup.add(this.previousGroup);
        this.controlGroup.add(this.nextGroup);
        this.controlGroup.add(this.workInProgressMesh);
        this.controlGroup.add(this.clickGroup);
        this.scene.add(this.controlGroup);

        this.nextLabelMesh.position.set(0, 0.2, 0);
        this.prevLabelMesh.position.set(0, 0.2, 0);
        this.nextControlsMesh.position.set(0, 0, 0);
        this.prevControlsMesh.position.set(0, 0, 0);
        this.workInProgressMesh.position.set(0, -0.9, 0);
        this.clickGroup.position.set(0, -0.5, 0);

        this.controlGroup.position.set(0, 0.4, 0);
        this.previousGroup.position.set(-0.4, 0, 0);
        this.nextGroup.position.set(0.4, 0, 0);
    }

    initManager() {
        this.displayProgress = { value: 0 };
        this.MIN_LOADING_TIME = 2.5; // Minimum time in seconds for the loading bar to complete
        this.assetsLoaded = false;

        this.manager.onProgress = (url, itemsLoaded, itemsTotal) => {
            const progress = itemsLoaded / itemsTotal;
            const duration = (progress - this.displayProgress.value) * this.MIN_LOADING_TIME;

            gsap.to(this.displayProgress, {
                value: progress,
                duration: Math.max(0.1, duration),
                ease: "none",
                overwrite: true,
                onUpdate: () => {
                    const p = this.displayProgress.value;
                    this.loadingText.text = `Loading Assets... ${Math.round(p * 100)}%`;
                    this.loadingText.sync();
                    this.progressBarFill.scale.x = p;
                },
                onComplete: () => {
                    if (this.displayProgress.value >= 0.999 && this.assetsLoaded) {
                        this.showBeginText();
                    }
                }
            });
        };

        this.manager.onLoad = () => {
            this.assetsLoaded = true;

            if (this.displayProgress.value < 0.999) {
                const duration = (1 - this.displayProgress.value) * this.MIN_LOADING_TIME;
                gsap.to(this.displayProgress, {
                    value: 1,
                    duration: Math.max(0.1, duration),
                    ease: "none",
                    overwrite: true,
                    onUpdate: () => {
                        const p = this.displayProgress.value;
                        this.loadingText.text = `Loading Assets... ${Math.round(p * 100)}%`;
                        this.loadingText.sync();
                        this.progressBarFill.scale.x = p;
                    },
                    onComplete: () => {
                        this.showBeginText();
                    }
                });
            } else {
                this.showBeginText();
            }
        };
    }

    showBeginText() {
        if (this.beginTextShown) return;
        this.beginTextShown = true;

        debugLog("All assets loaded. Starting experience...", "loading_c");
        this.isLoaded = true;

        gsap.timeline()
            .to([
                // this.instructionText, 
                this.loadingText,
                this.progressBarBg.material,
                this.progressBarFill.material
            ], {
                fillOpacity: 0,
                opacity: 0,
                duration: .2,
                onComplete: () => {
                    // this.instructionText.visible = false;
                    this.loadingText.visible = false;
                    this.progressBarBg.visible = false;
                    this.progressBarFill.visible = false;
                }
            })
            // .to(this.beginText, {
            //     fillOpacity: 1,
            //     duration: 0.5
            // })

            .to(this.clickGroup.scale, {
                x: 1,
                y: 1,
                z: 1,
                duration: 0.4,
                ease: "back.out(1.5)"
            })
    }

    bindEvents() {
        window.addEventListener('resize', () => {
            this.resize();
        });

        const handleClickOrTouch = (clientX, clientY) => {
            if (!this.isLoaded || this.experienceStarted) return;

            this.mouse.x = (clientX / window.innerWidth) * 2 - 1;
            this.mouse.y = -(clientY / window.innerHeight) * 2 + 1;

            this.raycaster.setFromCamera(this.mouse, this.camera);
            const intersects = this.raycaster.intersectObject(this.clickGroup, true);

            if (intersects.length > 0) {
                this.startExperience();
            }
        };

        window.addEventListener('click', (event) => {
            handleClickOrTouch(event.clientX, event.clientY);
        });

        window.addEventListener('touchstart', (event) => {
            if (event.touches && event.touches.length > 0) {
                handleClickOrTouch(event.touches[0].clientX, event.touches[0].clientY);
            }
        }, { passive: true });

        window.addEventListener('mousemove', (event) => {
            if (!this.isLoaded || this.experienceStarted) return;

            this.mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
            this.mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
            this.raycaster.setFromCamera(this.mouse, this.camera);

            const intersects = this.raycaster.intersectObject(this.clickGroup, true);
            document.body.style.cursor = intersects.length > 0 ? 'pointer' : 'default';
        });
    }

    startExperience() {

        this.experienceStarted = true;
        this.cursorController.setCursorState(CURSOR_STATES.LOCKED),
            document.body.style.cursor = 'default';

        const tl = gsap.timeline({
            onComplete: () => {
                this.isFinished = true; // Stop the render loop
                this.scene.clear();

                if (this.onStartExperience) this.onStartExperience();
            }
        });

        // 1. Burn the paper to the center
        // tl.to(this.uniforms.uProgress, {
        //     value: 1.5, // Burns everything except the center mask
        //     duration: 5.5,
        //     ease: "power4.inOut"
        // }, 0)

        // 2. Fly the remaining scrap and text away to the right
        // .to([this.mesh.position, this.beginText.position], {
        //     x: 3, // Fly out to the right side of the screen
        //     y: 0.5, // Slight upward drift for realism
        //     duration: 1.2,
        //     ease: "power2.in" // Start slow, accelerate out
        // }, "-=0.5") // Starts just before the burn finishes

        // 3. Add a little rotation to make it feel like a scrap caught in the wind
        // .to([this.mesh.rotation, this.beginText.rotation], {
        //     z: -Math.PI / 6, // Tilt right
        //     y: Math.PI / 8,
        //     duration: 1.2,
        //     ease: "power2.in"
        // }, "<")

        // 4. Fade out completely to ensure clean cleanup
        // tl.to(this.material, { opacity: 0, duration: 0.8 }, 1.4)
        // .to(this.beginText, { fillOpacity: 0, duration: 0.8 }, 1.4);
        tl.to(this.nextControlsMesh.material, { opacity: 0, duration: 1.5, ease: "power2.inOut", }, 0);
        tl.to(this.prevControlsMesh.material, { opacity: 0, duration: 1.5, ease: "power2.inOut", }, 0);
        tl.to(this.nextLabelMesh.material, { opacity: 0, duration: 1.5, ease: "power2.inOut", }, 0);
        tl.to(this.prevLabelMesh.material, { opacity: 0, duration: 1.5, ease: "power2.inOut", }, 0);
        tl.to(this.workInProgressMesh.material, { opacity: 0, duration: 1.5, ease: "power2.inOut", }, 0);
        tl.to(this.clickMat, { opacity: 0, duration: 1.5, ease: "power2.inOut", }, 0);

        tl.to(this.material, { opacity: 0, duration: 1.5, ease: "power2.inOut", }, 0);
        // tl.to(this.beginText, { fillOpacity: 0,duration: 0.5,ease: "power2.inOut",},0);
        tl.to(this.instructionText, { fillOpacity: 0, duration: 0.8, ease: "power2.inOut", }, 0);
        tl.to(this.scrollText, { fillOpacity: 0, duration: 0.8, ease: "power2.inOut", }, 0);
        if (this.desktopNoticeText) {
            tl.to(this.desktopNoticeText, { fillOpacity: 0, duration: 0.8, ease: "power2.inOut" }, 0);
        }
    }

    resize() {
        const width = window.innerWidth;
        const height = window.innerHeight
        const aspect = width / height;
        this.camera.left = -aspect;
        this.camera.right = aspect;
        this.camera.top = 1;
        this.camera.bottom = -1;
        this.camera.updateProjectionMatrix();

        if (this.mesh) {
            this.mesh.scale.set(aspect, 1, 1);
        }

        const deviceType = getDeviceType();

        let uiScale = 1.0;
        let controlGroupY = 0.4;
        let prevGroupX = -0.4;
        let nextGroupX = 0.4;
        let clickGroupY = -0.5;
        let wipMeshY = -0.9;
        let loadingTextY = 0;
        let loadingFontSize = 0.05;
        let barPosY = -0.2;
        let barWidth = 1.0;
        let noticePosY = -0.65;
        let noticeFontSize = 0.03;
        let noticeMaxWidth = 1.0;

        switch (deviceType) {
            case 1: // Mobile Landscape (aspect > 2)
                uiScale = Math.min(0.8, Math.max(0.65, 1.6 / aspect));
                controlGroupY = 0.35;
                prevGroupX = -0.5;
                nextGroupX = 0.5;
                clickGroupY = -0.5;
                wipMeshY = -0.9;
                loadingTextY = 0.02;
                loadingFontSize = Math.max(0.035, 0.05 * uiScale);
                barPosY = -0.15;
                barWidth = 0.85;
                noticePosY = -0.7;
                noticeFontSize = Math.max(noticeFontSize, noticeFontSize * uiScale);
                noticeMaxWidth = Math.min(2.5, (2 * aspect) * 0.75);
                break;

            case 3: // Mobile Portrait (aspect < 0.5)
                uiScale = Math.min(0.62, Math.max(0.48, aspect * 1.25));
                controlGroupY = 0.45;
                prevGroupX = -0.4;
                nextGroupX = 0.4;
                clickGroupY = -0.65;
                wipMeshY = -1.55;
                loadingTextY = 0.06;
                loadingFontSize = Math.max(0.03, 0.05 * uiScale);
                barPosY = -0.08;
                barWidth = Math.min(1.0, (2 * aspect) * 0.72);
                noticePosY = -0.22;
                noticeFontSize = Math.max(noticeFontSize, noticeFontSize * uiScale);
                noticeMaxWidth = Math.min(1.0, (2 * aspect) * 0.82);
                break;

            case 4: // Tablet / Standard Portrait (0.5 <= aspect < 1)
                uiScale = Math.min(0.85, Math.max(0.6, aspect * 1.15));
                controlGroupY = 0.42;
                prevGroupX = -0.4;
                nextGroupX = 0.4;
                clickGroupY = -0.6;
                wipMeshY = -1.2;
                loadingTextY = 0.04;
                loadingFontSize = Math.max(0.035, 0.05 * uiScale);
                barPosY = -0.12;
                barWidth = Math.min(1.0, (2 * aspect) * 0.72);
                noticePosY = -0.65;
                noticeFontSize = Math.max(noticeFontSize, noticeFontSize * uiScale);
                noticeMaxWidth = Math.min(1.2, (2 * aspect) * 0.82);
                break;

            case 2: // PC / Tablet Landscape (1 <= aspect <= 2)
            default:
                uiScale = Math.min(1.0, Math.max(0.75, Math.min(width / 1280, height / 800)));
                controlGroupY = 0.4 * uiScale;
                prevGroupX = -0.4;
                nextGroupX = 0.4;
                clickGroupY = -0.5;
                wipMeshY = -0.9;
                loadingTextY = 0;
                loadingFontSize = 0.05 * uiScale;
                barPosY = -0.2 * uiScale;
                barWidth = Math.min(1.0, (2 * aspect) * 0.6) * uiScale;
                noticePosY = -0.65;
                noticeFontSize = 0.024 * uiScale;
                noticeMaxWidth = Math.min(1.8, (2 * aspect) * 0.8);
                break;
        }

        if (this.controlGroup) {
            this.controlGroup.position.set(0, controlGroupY, 0);
            this.controlGroup.scale.set(uiScale, uiScale, 1);
        }

        if (this.previousGroup) {
            this.previousGroup.position.set(prevGroupX, 0, 0);
        }

        if (this.nextGroup) {
            this.nextGroup.position.set(nextGroupX, 0, 0);
        }

        if (this.clickGroup) {
            this.clickGroup.position.set(0, clickGroupY, 0);
        }

        if (this.workInProgressMesh) {
            this.workInProgressMesh.position.set(0, wipMeshY, 0);
        }

        if (this.loadingText) {
            this.loadingText.position.set(0, loadingTextY, 0.1);
            this.loadingText.fontSize = loadingFontSize;
            this.loadingText.sync();
        }

        if (this.progressBarGroup) {
            this.progressBarGroup.position.set(0, barPosY, 0.1);
            this.progressBarGroup.scale.set(barWidth, uiScale, 1);
        }

        if (this.instructionText) {
            this.instructionText.fontSize = Math.max(0.035, 0.06 * uiScale);
            this.instructionText.sync();
        }

        if (this.scrollText) {
            this.scrollText.fontSize = Math.max(0.035, 0.06 * uiScale);
            this.scrollText.sync();
        }
        if (this.desktopNoticeText) {
            const isMobileScreen = (deviceType === 1 && (height <= 600 || width <= 1024)) ||
                deviceType === 3 ||
                width <= 768 ||
                (/Android|webOS|iPhone|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) && (width <= 1024 || height <= 1024));

            this.desktopNoticeText.visible = Boolean(isMobileScreen && !this.experienceStarted);
            this.desktopNoticeText.position.set(0, noticePosY, 0.1);
            this.desktopNoticeText.fontSize = noticeFontSize;
            this.desktopNoticeText.maxWidth = noticeMaxWidth;
            this.desktopNoticeText.sync();
        }
    }

    update(time) {
        // Use the new isFinished flag to know exactly when to stop rendering the overlay
        if (!this.isFinished) {
            this.uniforms.uTime.value = time;

            const prevAutoClear = this.renderer.autoClear;
            this.renderer.autoClear = false;

            this.renderer.clearDepth();
            this.renderer.render(this.scene, this.camera);

            this.renderer.autoClear = prevAutoClear;
        }
    }


    getGLTFLoader() {
        if (!this.isLoaded) return this.startupGltfLoader;

        // If loaded, create the lazy loader if it doesn't exist yet
        if (!this.lazyGltfLoader) {
            this.lazyGltfLoader = new GLTFLoader();
            this.lazyGltfLoader.setDRACOLoader(this.dracoLoader); // Safe to reuse Draco workers
        }
        return this.lazyGltfLoader;
    }

    getTextureLoader(lazy = false) {
        if (!this.isLoaded && !lazy) return this.startupTextureLoader;

        if (!this.lazyTextureLoader) {
            this.lazyTextureLoader = new THREE.TextureLoader();
        }
        return this.lazyTextureLoader;
    }

    getAudioLoader() {
        if (!this.isLoaded) return this.startupAudioLoader;

        if (!this.lazyAudioLoader) {
            this.lazyAudioLoader = new THREE.AudioLoader();
        }
        return this.lazyAudioLoader;
    }
}