import * as THREE from 'three';
import { Text, getSelectionRects } from 'troika-three-text'

import gsap from "gsap"
import { debugLog } from "../../../debugger/debugLog.js";
import { COLORS } from '../../../siteData.js';

export default async function section2Forward(animManager) {

    debugLog("Section 2", "sec2_debug");
    const sectionDuration = 5;
    const butterflyPath = "paths/butterflySec2_1.json";
    const snakePath = "paths/snakeSec2.json";

    animManager.section2ForwardTl = gsap.timeline({ paused: animManager.typeSectional })
    const phasingData = { progress: 0 };

    animManager.section2ForwardTl
        .to(phasingData, {
            progress: sectionDuration, // Animate from 0 to 1
            duration: sectionDuration,
            onUpdate: () => {
                animManager.moonMaterial.uniforms.uTime.value = animManager.moonPhasingData.progress + phasingData.progress; // One full rotation for the phase cycle            
            },
            onComplete: () => {
                debugLog("moon completed section 2 ", "sec2_debug");
                animManager.moonPhasingData.progress = animManager.moonPhasingData.progress + phasingData.progress;
                animManager.autoCloudSway = true;
            }
        }, 0);


    const butterflyCurveId = await animManager.curveEditor.loadCurveFromPath(butterflyPath, "bfly-sec2-fwd");
    const butterflyCurve1 = animManager.curveEditor.curves[butterflyCurveId].curve3;

    const butterflyFlightData = { progress: 0 };
    animManager.section2ForwardTl.to(butterflyFlightData, {
        progress: 1,
        duration: sectionDuration,
        ease: "sine.in",
        onUpdate: () => {
            let position = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress, 0, 0);
            animManager.butterfly.position.copy(position);
            if (butterflyFlightData.progress + 0.01 < 1) {
                let lookAtPosition = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress + 0.01, 0, 0);
                animManager.butterfly.lookAt(lookAtPosition);
            }
        },
    }, 2)
        .call(() => {
            animManager.flickerComicPanelsOn();
        }, [], ">0.5")
        // .to(animManager.grassMesh.grassMaterial.uniforms.uColorIntensities.value, {
        //     [0]: 0.4,
        //     duration: 3,
        //     ease: "power2.out",
        //     onStart: () => {
        //         debugLog("grass2 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
        //     },
        // }, ">0.4")

        .to(animManager.grassMesh.grassMaterial.uniforms.uColorRadii.value, {
            keyframes: [
                { [0]: 1200, duration: 0.05 },
                { [0]: 0, duration: 0.1 },
                { [0]: 640, duration: 0.05 },
                { [0]: 0, duration: 0.05 },
                { [0]: 400, duration: 0.05 },
                { [0]: 800, duration: 0.1 }
            ],
            // duration: 3,
            // ease: "back.out(1.2)",
            onStart: () => {
                debugLog("grass3 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
                animManager.grassMesh.grassMaterial.uniforms.uColorIntensities.value[0] = 1.0;
            },
        }, "<");

    const snakeCurveId = await animManager.curveEditor.loadCurveFromPath(snakePath, "snk-sec2-fwd");
    const snakeCurve1 = animManager.curveEditor.curves[snakeCurveId].curve3;

    const snakeMotionData = { progress: 0 };
    animManager.section2ForwardTl.to(snakeMotionData, {
        progress: 1, // Animate from 0 to 1
        duration: sectionDuration - 1,
        ease: "power1.out",
        onUpdate: () => {
            let position = animManager.getResponsivePoint(snakeCurve1, snakeMotionData.progress, 0, animManager.bgMeshOffest.y);
            animManager.snake.update(position, snakeMotionData.progress);
        },
        onComplete: () => {
            animManager.setAboutContent(1);
        }


    }, 1)
        .call(() => {
            debugLog("movement phase completed ", "sec2_debug, morph");
            let position = animManager.getResponsivePoint(snakeCurve1, 1, 0, animManager.bgMeshOffest.y);
            position.y += 20;
            animManager.snake.toggleMorph({
                position: position, // Position on screen/world
                duration: 1.5,
                ease: "power1.out",
            });

        }, [], ">=-1");

    const headerRightLastLetterPos = await animManager.getLetterWorldPosition(animManager.headerRight, animManager.headerRight.text.length - 1);
    animManager.quoteGroupStartPos = animManager.quoteGroup.position;

    animManager.section2ForwardTl.to(animManager.quoteGroup.position, { y: headerRightLastLetterPos.y, duration: 5, ease: 'power2.inOut' }, 0)
    animManager.section2ForwardTl.to(animManager.quoteGroup.position, { z: 25, duration: 2, ease: 'power1.in' }, 0)

        .to(animManager.quoteCloud.cloud.material.uniforms.threshold, { value: 0.25, duration: 1.0, ease: "power1.out" }, "<")
        .to(animManager.fog1.cloud.material.uniforms.threshold, { value: 0.25, duration: 1.0, ease: "power1.out" }, "<")
        .to(animManager.quoteTextEnglish.material, { opacity: 0, duration: 1, ease: 'power1.inOut' }, "<")
        .to(animManager.quoteCloud.cloud.scale, {
            x: 0.4,
            y: 0.8,
            z: 1,
            duration: 1,
            ease: "back.out(1.5)"
        }, ">")
        .to(animManager.cloudDuplicate.scale, {
            x: 0.4,
            y: 0.5,
            z: 1,
            duration: 1,
            ease: "back.out(1.5)"
        }, "<")
        .to(animManager.quoteCloud.cloud.position, { x: 400, duration: 5, ease: "back.out(1.5)" }, "<")
        .to(animManager.cloudDuplicate.position, { x: -300, duration: 5, ease: "back.out(1.5)" }, "<")


    // animManager.section2ForwardTl.to(animManager.aboutTextUniforms.uDissolve, { value: 1.2, duration: 2.5, ease: "none" }, 0)
    animManager.section2ForwardTl.to(animManager.aboutComicBase.material, { opacity: 1.0, duration: 1, ease: "none" }, 1.5);

    const targetTextColor = new THREE.Color(COLORS.content_background);
    animManager.section2ForwardTl.to(animManager.backdrop.material.uniforms.uOpacity, {
        value: 1.1,         // Target fully visible
        duration: 2,        // Over 3 seconds
        ease: "bounce.out(1.5)",
        onStart: () => {
            animManager.backdrop.visible = true;
            animManager.animateBackdrop = true;
        }
    }, 1);


    animManager.section2ForwardTl.to(animManager.backgroundMesh.material, {
        opacity: 0,
        duration: 1,
        ease: "power2.inOut"
    }, 0);

    animManager.section2ForwardTl.to(animManager.grassMesh.grassUniforms.opacity, {
        value: 1.2, duration: 1, ease: "none",
        onStart: () => {
            animManager.growGrass();
            animManager.grassMesh.mesh.visible = true;
            animManager.animateGrass = true;
        }
    }, 0);

    animManager.section2ForwardTl.to(animManager.fog1.cloud.material, {
        opacity: 0.1, duration: 2.0,
        onStart: () => {
            animManager.fog1.cloud.visible = true;
            animManager.fog2.visible = true;
            animManager.renderFog = true;
        }
    }, 1);


    if (animManager.aboutComicTheater) {
        const theaterMesh = animManager.aboutComicTheater;
        const theaterWidth = (theaterMesh.geometry?.parameters?.width || 1280) * theaterMesh.scale.x;
        const leftEdge = animManager.leftEdge ?? -(animManager.visibleWidth / 2);
        const offscreenLeftX = leftEdge - (theaterWidth / 2 + 100);

        theaterMesh.position.x = offscreenLeftX;

        animManager.section2ForwardTl.fromTo(theaterMesh.position,
            { x: offscreenLeftX },
            {
                x: 0,
                duration: 2.5,
                ease: "back.out(1.1)",
                onStart: () => {
                    theaterMesh.visible = true;

                },
            }, 2.5)
            .to(animManager.aboutTitleUniforms.uTextColor.value, {
                r: targetTextColor.r,
                g: targetTextColor.g,
                b: targetTextColor.b,
                duration: 0.8,
                ease: "bounce.out(1.5)"
            }, "+=0.5")
            // .to(animManager.aboutNavItems[0].text.material.color, {
            //     r: targetTextColor.r,
            //     g: targetTextColor.g,
            //     b: targetTextColor.b,
            //     duration: 0.8,
            //     ease: "bounce.out(1.5)"
            // }, "<")
            // .to(animManager.aboutNavItems[1].text.material.color, {
            //     r: targetTextColor.r,
            //     g: targetTextColor.g,
            //     b: targetTextColor.b,
            //     duration: 0.8,
            //     ease: "bounce.out(1.5)"
            // }, "<")
            // .to(animManager.aboutNavItems[2].text.material.color, {
            //     r: targetTextColor.r,
            //     g: targetTextColor.g,
            //     b: targetTextColor.b,
            //     duration: 0.8,
            //     ease: "bounce.out(1.5)"
            // }, "<")
            .to(animManager.aboutNavItems[0].underline.material.color, {
                r: targetTextColor.r,
                g: targetTextColor.g,
                b: targetTextColor.b,
                duration: 0.8,
                ease: "bounce.out(1.5)"
            }, "<")
            .to(animManager.aboutNavItems[1].underline.material.color, {
                r: targetTextColor.r,
                g: targetTextColor.g,
                b: targetTextColor.b,
                duration: 0.8,
                ease: "bounce.out(1.5)"
            }, "<")
            .to(animManager.aboutNavItems[2].underline.material.color, {
                r: targetTextColor.r,
                g: targetTextColor.g,
                b: targetTextColor.b,
                duration: 0.8,
                ease: "bounce.out(1.5)"
            }, "<")
            .to(animManager.aboutNavLeft.scale, {
                x: 1,
                y: 1,
                z: 1,
                duration: 0.4,
                ease: "back.out(1.5)"
            }, ">")
            .to(animManager.aboutNavRight.scale, {
                x: 1,
                y: 1,
                z: 1,
                duration: 0.4,
                ease: "back.out(1.5)"
            }, ">");
    }
    debugLog("Section 2 end", "sec2_debug");
}