import * as THREE from 'three';
import { Text, getSelectionRects } from 'troika-three-text'

import gsap from "gsap"
import { debugLog } from "../../../debugger/debugLog.js";
import { COLORS } from '../../../siteData.js';

export default async function section3Forward(animManager) {

    debugLog("Section 3", "sec3_debug");

    animManager.section3ForwardTl = gsap.timeline({ paused: animManager.typeSectional })

    const sectionDuration = 5;
    const butterflyPath = "paths/butterflySec3.json";
    const snakePath = "paths/snakeSec3_2.json";

    const phasingData = { progress: 0 };

    // moon 
    animManager.section3ForwardTl
        .to(phasingData, {
            progress: sectionDuration, // Animate from 0 to 1
            duration: sectionDuration,
            // ease: "power1.inOut",
            onUpdate: () => {
                animManager.moonMaterial.uniforms.uTime.value = animManager.moonPhasingData.progress + phasingData.progress; // One full rotation for the phase cycle            
            },
            onComplete: () => {
                debugLog("moon completed section 3 ", "sec3_debug");
                animManager.moonPhasingData.progress = animManager.moonPhasingData.progress + phasingData.progress;
            }
        }, 0);

    animManager.section3ForwardTl.call(() => {
        debugLog("morph to snake", "tl_rev");
        animManager.snake.toggleMorph({
            duration: 1.5,
            ease: "power1.out",
        });
    }, [], 0);

    // animManager.section3ForwardTl.call(() => {
    //     animManager.toggleGrass();
    // },[], 0);

    animManager.section3ForwardTl.to(animManager.grassMesh.grassUniforms.opacity, {
        value: 0, duration: 1, ease: "none",
        onComplete: () => {
            animManager.disableGrass();
        }
    }, 0);
    animManager.section3ForwardTl.to(animManager.grassMesh.grassMaterial.uniforms.uColorIntensities.value, {
        [0]: 0.0,
        duration: 1,
        ease: "power2.out",
        onStart: () => {
            debugLog("grass2 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
        },
    }, 0)
        .to(animManager.grassMesh.grassMaterial.uniforms.uColorRadii.value, {
            [0]: 0.0, // Your target full size
            duration: 1,
            ease: "back.out(1.2)",
            onStart: () => {
                debugLog("grass3 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
            },
        }, "<")
        .to(animManager.backdrop.material.uniforms.uOpacity, {
            value: 0,         // Target fully visible
            duration: 1,        // Over 3 seconds
            ease: "power2.out",
            onComplete: () => {
                animManager.backdrop.visible = false;
                animManager.animateBackdrop = false;
            }
        }, "<");

    const butterflyCurveId = await animManager.curveEditor.loadCurveFromPath(butterflyPath, "bfly-sec3-fwd");
    const butterflyCurve1 = animManager.curveEditor.curves[butterflyCurveId].curve3;

    const butterflyFlightData = { progress: 0 };
    animManager.section3ForwardTl.to(butterflyFlightData, {
        progress: 1,
        duration: sectionDuration - 2,
        ease: "sine.in",
        onUpdate: () => {
            let position = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress, 0, 0);

            animManager.butterfly.position.copy(position);

            if (butterflyFlightData.progress + 0.01 < 1) {
                let lookAtPosition = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress + 0.01, 0, 0);
                animManager.butterfly.lookAt(lookAtPosition);
            }
            // const snakePos = position.add(animManager.bgMeshOffest);
            // animManager.snake.update(snakePos, butterflyFlightData.progress);

        }
    }, 1);

    const snakeCurveId = await animManager.curveEditor.loadCurveFromPath(snakePath, "snk-sec3-fwd");
    const snakeCurve1 = animManager.curveEditor.curves[snakeCurveId].curve3;

    const snakeMotionData = { progress: 0 };
    animManager.section3ForwardTl.to(snakeMotionData, {
        progress: 1, // Animate from 0 to 1
        duration: sectionDuration - 1,
        ease: "power1.out",
        onUpdate: () => {

            let position = animManager.getResponsivePoint(snakeCurve1, snakeMotionData.progress, 0, animManager.bgMeshOffest.y);
            animManager.snake.update(position, snakeMotionData.progress);
        },

    }, 1);

    animManager.section3ForwardTl.to(animManager.aboutTitleUniforms.uDissolve, {
        value: 1.2, duration: 2.5, ease: "none",
        onComplete: () => {
            debugLog("Hiding nav items", "about_nav_bug2");
            animManager.aboutNavItems.forEach((buttonObj, index) => {
                buttonObj.text.layers.set(1);

            });
        },
    }, 0)
        .to(animManager.aboutNavItems[0].underline.material, {
            linewidth: 0, duration: 0.5, ease: "none",
            onUpdate: () => {
                animManager.aboutNavItems[0].underline.material.needsUpdate = true;
            },
        }, "<")
        .to(animManager.aboutNavItems[1].underline.material, {
            linewidth: 0, duration: 0.5, ease: "none",
            onUpdate: () => {
                animManager.aboutNavItems[1].underline.material.needsUpdate = true;
            },
        }, "<")
        .to(animManager.aboutNavItems[2].underline.material, {
            linewidth: 0, duration: 0.5, ease: "none",
            onUpdate: () => {
                animManager.aboutNavItems[2].underline.material.needsUpdate = true;
            },
        }, "<")

    animManager.section3ForwardTl.to(animManager.backgroundMesh.material, {
        opacity: 1,
        duration: 2,
        ease: "power2.inOut"
    }, 0);

    const targetBgColor = new THREE.Color(COLORS.background);
    animManager.section3ForwardTl.to(animManager.scene.background, {
        r: targetBgColor.r,
        g: targetBgColor.g,
        b: targetBgColor.b,
        duration: 2,
        ease: "power2.inOut"
    }, 0);

    animManager.section3ForwardTl.to(animManager.aboutUnderline.material, {
        linewidth: 0, duration: 2.5, ease: "expo.inOut",
        onUpdate: () => {
            animManager.aboutUnderline.material.needsUpdate = true;
        },
    }, 0);

    animManager.testimonialStartPosY = animManager.testimonialGroup.position.y;
    animManager.workGroupStartPosY = animManager.workGroup.position.y;

    animManager.section3ForwardTl.to(animManager.workGroup.position, { y: animManager.workGroup.position.y + (620 * animManager.scaleFactor), duration: 2, ease: 'power2.inOut' }, 0);
    animManager.section3ForwardTl.to(animManager.testimonialGroup.position, { y: animManager.testimonialGroup.position.y + (550 * animManager.scaleFactor), duration: 2, ease: 'power2.inOut' }, 0);

    if (animManager.aboutComicTheater) {
        const theaterMesh = animManager.aboutComicTheater;
        const theaterWidth = (theaterMesh.geometry?.parameters?.width || 1280) * theaterMesh.scale.x;
        const rightEdge = animManager.rightEdge ?? (animManager.visibleWidth / 2);
        const offscreenRightX = rightEdge + (theaterWidth / 2 + 100);

        theaterMesh.position.x = offscreenRightX;

        animManager.section3ForwardTl.to(animManager.aboutComicBase.material, { opacity: 0.0, duration: 1, ease: "none" }, 0);

        animManager.section3ForwardTl.fromTo(theaterMesh.position,
            { x: 0 },
            {
                x: offscreenRightX,
                duration: 1.5,
                ease: "back.out(1.1)",
                onStart: () => {
                    animManager.setAboutContent(-1, true);
                },
            }, 0);
    }

    animManager.section3ForwardTl.to(animManager.fog1.cloud.material, {
        opacity: 0.0, duration: 1.0,
        onComplete: () => {
            animManager.fog1.cloud.visible = false;
            animManager.fog2.visible = false;
            animManager.renderFog = false;
        }
    }, 0);

    debugLog("Section 3 end", "sec3_debug");
}