export class DebugManager {
    /**
     * @param {Array} guis - An array of lil-gui instances
     * @param {Object} stats - The stats.js instance (optional)
     * @param {string} toggleKey - The keyboard key to trigger the toggle
     */
    constructor(guis = [], stats = null, toggleKey = 'h') {
        // Ensure guis is always an array, even if they pass a single instance
        this.guis = Array.isArray(guis) ? guis : [guis];
        this.stats = stats;
        this.stats.showPanel(0);
        // this.stats.showPanel(1);
        // this.stats.showPanel(2);
        this.toggleKey = toggleKey;
        this.isVisible = true;

        // Bind the method so 'this' refers to the class instance inside the event listener
        this._handleKeyDown = this._handleKeyDown.bind(this);

        this.init();
    }

    init() {
        window.addEventListener('keydown', this._handleKeyDown);
    }

    // Allows you to add more guis later if needed
    addGui(gui) {
        this.guis.push(gui);
    }

    _handleKeyDown(event) {
        if (window.isContactCardActive)
            return;
        if (event.key === this.toggleKey) {
            this.toggle();
        }
    }

    toggle() {
        this.isVisible = !this.isVisible;

        // Toggle all registered lil-gui instances
        this.guis.forEach(gui => {
            if (gui) {
                this.isVisible ? gui.show() : gui.hide();
            }
        });

        // Toggle stats.js if it was provided
        if (this.stats && this.stats.dom) {
            this.stats.dom.style.display = this.isVisible ? 'block' : 'none';
        }
    }

    // Good practice: a way to clean up event listeners if you destroy your 3D scene
    dispose() {
        window.removeEventListener('keydown', this._handleKeyDown);
        this.guis = [];
        this.stats = null;
    }
}