import * as THREE from 'three';

export class Cat {
    constructor(scene, loader, clock) {
        this.scene = scene;

        this.model = null;
        this.loader = loader;
        this.mixer = null;
        this.actions = {};
        this.activeAction = null;

        this.clock = clock;
        
        // --- 1. Follow Behavior Properties ---
        this.targetModel = null;          // The butterfly
        this.isFollowingEnabled = false;  // Toggle behavior
        this.stopDistance = 250;          // How close it gets (adjust based on your 500 moveSpeed scale)
        this.followDelayFactor = 0.005;    // Lower = more delay/sluggish, Higher = snappier'

        // --- 3. Input Tracking ---
        this.keys = { w: false, a: false, s: false, d: false };

        window.addEventListener('keydown', (e) => {
            const key = e.key.toLowerCase();
            if (this.keys.hasOwnProperty(key)) this.keys[key] = true;
        });

        window.addEventListener('keyup', (e) => {
            const key = e.key.toLowerCase();
            if (this.keys.hasOwnProperty(key)) this.keys[key] = false;
        });
    }

    enableFollowBehavior(targetModel, enabled = true) {
        this.targetModel = targetModel;
        this.isFollowingEnabled = enabled;
    }

    enabled(enabled = true) {
        this.model.visible = enabled; 
    }

    async loadCat() {

        try {
            
            const gltf = await this.loader.loadAsync('models/Cat.glb');
            this.model = gltf.scene;
            this.model.visible = false; 
            // this.model.scale.set(50, 50, 50);
            // this.model.position.set(0, 0, 0);
            this.scene.add(this.model);

            this.model.traverse((child) => {
                if (child.isMesh) {
                    const oldMat = child.material;
                    child.material = new THREE.MeshBasicMaterial({  
                        map: oldMat.map,
                        color: oldMat.color,
                        side: THREE.DoubleSide
                    });
                }
            });

            // Setup the Animation Mixer
            this.mixer = new THREE.AnimationMixer(this.model);

            // Extract animations and store them in our dictionary
            gltf.animations.forEach((clip) => {
                this.actions[clip.name] = this.mixer.clipAction(clip);
            });

            // Start with the 'wait' animation
            if (this.actions['Walk']) {
                this.activeAction = this.actions['Walk'];
                this.activeAction.play();
            } else {
                console.warn("Animation 'wait' not found. Check your GLB animation names.");
            }
        } catch (error) {
            console.error("Error loading the cat model:", error);
        }
    }   

    fadeToAction(name, duration = 0.2) {
        // console.log("Fading to action: " + name);
        const nextAction = this.actions[name];
        if (!nextAction)
            return;
        if(this.activeAction === nextAction)
        {
            this.activeAction.play();
            return;
        }

        nextAction.reset().fadeIn(duration).play();
        this.activeAction.fadeOut(duration);
        this.activeAction = nextAction;
    }

    updateMovement(delta) {
        if (!this.model) return; // Don't run if cat isn't loaded yet
        
        let isMoving = false;

        // --- 3. Check which behavior is active ---
        if (this.isFollowingEnabled && this.targetModel) {
            
            const targetPosition = this.targetModel.position.clone();
            targetPosition.y = this.model.position.y;

            // Calculate distance to the butterfly
            const distance = this.model.position.distanceTo(targetPosition);

            if (distance > this.stopDistance) {
                // Lerp creates the natural "delayed follow" effect
                this.model.position.lerp(targetPosition, this.followDelayFactor);
                
                // Make the cat face the butterfly
                this.model.lookAt(targetPosition);
                
                isMoving = true;
            } else {
                isMoving = false; // Close enough, come to rest
            }

        } else {
            // --- Fallback to your original manual controls ---
            const moveSpeed = 500 * delta;
            const rotationSpeed = Math.PI * delta;

            if (this.keys.w) { 
                this.model.translateZ(moveSpeed); 
                isMoving = true; 
            }
            if (this.keys.s) { 
                this.model.translateZ(-moveSpeed); 
                isMoving = true; 
            }
            if (this.keys.a) { 
                this.model.rotation.y += rotationSpeed; 
                isMoving = true; 
            }
            if (this.keys.d) { 
                this.model.rotation.y -= rotationSpeed; 
                isMoving = true; 
            }
        }

        // Switch animations based on movement state
        if (isMoving) {
            this.fadeToAction('Walk');
        } else {
            this.fadeToAction('Wait');
        }
    }

    animate(delta) {
               
        // Update the animation mixer
        if (this.mixer) 
        {
            this.mixer.update(delta);
            // console.log("mixer udpdating v" + delta);
        }
            
        
        // Update position and check key presses
        this.updateMovement(delta);
        
    }
    
    
}
