// src/lifecycleManager.js
import { gsap } from 'gsap';
import * as THREE from 'three';

export function setupTabLifecycle({
    onPause,
    onResume,
    pauseOnWindowBlur = false // Set to true if you also want pause when clicking outside window
}) {
    let isPaused = false;

    function evaluateState() {
        const shouldPause = document.hidden || (pauseOnWindowBlur && !document.hasFocus());

        if (shouldPause && !isPaused) {
            isPaused = true;

            // 1. Pause GSAP
            gsap.globalTimeline.pause();
            gsap.ticker.sleep();

            // 2. Suspend Audio if active
            if (THREE.AudioContext && THREE.AudioContext.getContext) {
                const ctx = THREE.AudioContext.getContext();
                if (ctx && ctx.state === 'running') ctx.suspend();
            }

            // 3. Custom loop pause callback
            if (onPause) onPause();

        } else if (!shouldPause && isPaused) {
            isPaused = false;

            // 1. Resume Audio if suspended
            if (THREE.AudioContext && THREE.AudioContext.getContext) {
                const ctx = THREE.AudioContext.getContext();
                if (ctx && ctx.state === 'suspended') ctx.resume();
            }

            // 2. Custom loop resume callback (syncs clock oldTime before GSAP resumes)
            if (onResume) onResume();

            // 3. Resume GSAP
            gsap.ticker.wake();
            gsap.globalTimeline.resume();
        }
    }

    // Listen to tab switch / minimize
    document.addEventListener('visibilitychange', evaluateState);

    // Listen to window focus/blur (optional)
    if (pauseOnWindowBlur) {
        window.addEventListener('blur', evaluateState);
        window.addEventListener('focus', evaluateState);
    }

    return {
        isPaused: () => isPaused,
        destroy: () => {
            document.removeEventListener('visibilitychange', evaluateState);
            if (pauseOnWindowBlur) {
                window.removeEventListener('blur', evaluateState);
                window.removeEventListener('focus', evaluateState);
            }
        }
    };
}
