
import { gsap } from "gsap";
import { Observer } from "gsap/Observer";

import { debugLog } from "./debugger/debugLog.js";


gsap.registerPlugin(Observer);

export function createScrollController(sectionAnimManager) {
  // return;
  // 1. DESKTOP OBSERVER (Mouse Wheel & Trackpad)
  Observer.create({
    type: "wheel",
    // Scroll wheel DOWN -> Next Section
    onDown() {
      if (window.isContactCardActive) return;
      debugLog("Desktop onDown - Next", "scroll_obs");
      sectionAnimManager.next();
    },
    // Scroll wheel UP -> Prev Section
    onUp() {
      if (window.isContactCardActive) return;
      debugLog("Desktop onUp - Prev", "scroll_obs");
      sectionAnimManager.prev();
    },
    tolerance: 10,
    preventDefault: true
  });

  // 2. MOBILE OBSERVER (Touch Screens)
  Observer.create({
    type: "touch",
    // Swipe finger UP (scrolling down page) -> Next Section
    onUp() {
      if (window.isContactCardActive) return;
      debugLog("Mobile onUp - Next", "scroll_obs");
      sectionAnimManager.next();
    },
    // Swipe finger DOWN (scrolling up page) -> Prev Section
    onDown() {
      if (window.isContactCardActive) return;
      debugLog("Mobile onDown - Prev", "scroll_obs");
      sectionAnimManager.prev();
    },
    tolerance: 10,
    preventDefault: true
  });

}


// Note: You will need to pass your main GSAP timeline to this function 
// instead of (or alongside) the sectionAnimManager.
export function createScrubbingScrollController(masterTimeline) {

  // This variable holds where we *want* the timeline to be based on user input.
  let targetProgress = 0;

  // Tuning Variables (Adjust these to feel right in your project)
  const scrollSensitivity = 0.0001; // How much progress is added per pixel scrolled
  const smoothDuration = 0.5;       // How long it takes to catch up to the scroll wheel (higher = smoother, lower = snappier)

  Observer.create({
    // Enable touch for swiping on mobile devices
    type: "wheel,touch",

    // We use onChange to fire continuously while scrolling/swiping, 
    // rather than just checking the initial up/down flick.
    onChange(self) {
      if (window.isContactCardActive) return;
      debugLog("Scrubbing. DeltaY: " + self.deltaY, "scroll_scrub");

      // 1. Calculate the new target progress based on scroll direction and speed
      // (You may need to change += to -= depending on your preferred scroll direction)
      targetProgress += self.deltaY * scrollSensitivity;

      // 2. Clamp the progress so it stays strictly between 0 (start) and 1 (end)
      targetProgress = gsap.utils.clamp(0, 1, targetProgress);

      // 3. Smoothly animate the timeline to the new target progress.
      // This is the "secret sauce" that prevents spamming from breaking the animation.
      // Overwrite: "auto" ensures that rapid new scroll events seamlessly override older ones.
      gsap.to(masterTimeline, {
        progress: targetProgress,
        duration: smoothDuration,
        ease: "power2.out",
        overwrite: "auto"
      });
    },

    tolerance: 10,
    preventDefault: true
  });
}
