import * as THREE from 'three';
import { Text, getSelectionRects } from 'troika-three-text'

import gsap from "gsap"
import { debugLog } from "../../../debugger/debugLog.js";

/**
 * @param {import("./sectionalAnimationManager.js").SectionalAnimationManager} animManager
 */
export default async function section1Back

    (animManager) {

    debugLog("Section 1", "sec1_debug");

    const sectionDuration = 10;
    const butterflyPath = "paths/butterflySec1.json";
    const snakePath = "paths/snakeSec1.json";

    animManager.section1BackTl = gsap.timeline({ paused: animManager.typeSectional })


    const crescentValue = 9.8;

    // moon 
    animManager.section1BackTl
        .to(animManager.moonPhasingData, {
            progress: 0, // Animate from 0 to 1
            duration: 6,
            onUpdate: () => {
                animManager.moonMaterial.uniforms.uTime.value = animManager.moonPhasingData.progress; // One full rotation for the phase cycle

            },
            onStart: () => {
                debugLog("normal - moon start section 1 ", "sec1Alt_debug");
            }
        }, 0)
        .to(animManager.moonMaterial.uniforms.uPhaseStrength, {
            value: 0,
            duration: 2,
        }, ">")
        .to(animManager.moonMaterial.uniforms.uTextureReveal, {
            value: 0,
            duration: 2,
        }, ">");



    const butterflyCurveId = await animManager.curveEditor.loadCurveFromPath(butterflyPath, "bfly-sec1-bck");
    const butterflyCurve1 = animManager.curveEditor.curves[butterflyCurveId].curve3;

    debugLog("Butterfly Curve Loaded for Section 1 " + animManager.scaleFactor, "sec1_debug");
    let startPoint = butterflyCurve1.getPoint(0);
    startPoint = animManager.getResponsivePoint(butterflyCurve1, 0, 0, 0);
    let spawnPoint = startPoint.clone();
    spawnPoint.x = animManager.rightEdge; // start off-screen to the right
    spawnPoint.y += (50 * animManager.scaleFactorVec.y); // adjust for any vertical scaling
    animManager.butterfly.position.copy(spawnPoint);
    const butterflyFlightData = { progress: 1 };
    animManager.section1BackTl.to(butterflyFlightData, {
        progress: 0,
        duration: sectionDuration - 2,
        ease: "sine.in",
        onUpdate: () => {
            let position = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress, 0, 0);
            animManager.butterfly.position.copy(position);

            if (butterflyFlightData.progress + 0.01 < 1) {
                let lookAtPosition = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress + 0.01, 0, 0);
                animManager.butterfly.lookAt(lookAtPosition);
            }

        },
    }, 0);

    const snakeCurveId = await animManager.curveEditor.loadCurveFromPath(snakePath, "snk-sec1-bck");
    const snakeCurve1 = animManager.curveEditor.curves[snakeCurveId].curve3;

    const snakeMotionData = { progress: 1 };
    animManager.section1BackTl.to(snakeMotionData, {
        progress: 0, // Animate from 0 to 1
        duration: sectionDuration - 2,
        ease: "back",
        onUpdate: () => {
            if (snakeMotionData.progress < 0)
                return;

            let position = animManager.getResponsivePoint(snakeCurve1, snakeMotionData.progress, 0, animManager.bgMeshOffest.y);
            animManager.snake.update(position, snakeMotionData.progress);
        }
    }, 2);

    animManager.section1BackTl.to(animManager.quoteText.material, { opacity: 1, duration: sectionDuration, ease: 'power1.inOut' }, 0)
    animManager.section1BackTl.to(animManager.quoteTextEnglish.material, { opacity: 0, duration: sectionDuration, ease: 'power1.inOut' }, 0); // at the same time as the previous

    debugLog("Section 1 end " + startPoint, "sec_debug");
    return startPoint;
}