export function createFilledRect(width, height, color, name = "") {
  const boxGeometry = new THREE.PlaneGeometry(width, height);
  const boxmMat = new THREE.MeshBasicMaterial({
    color: color, // Your hex color
    side: THREE.DoubleSide,
    transparent: true
  });

  const filledBox = new THREE.Mesh(boxGeometry, boxmMat);
  filledBox.name = name;

  return filledBox;
}

export function createFilledRectWithBorder(width, height, baseColor, linewidth, borderColor, name = "") {
  const boxGeometry = new THREE.PlaneGeometry(width, height);
  const boxmMat = new THREE.MeshBasicMaterial({
    color: baseColor, // Your hex color
    side: THREE.DoubleSide,
    transparent: true
  });

  const filledBox = new THREE.Mesh(boxGeometry, boxmMat);
  filledBox.name = name;

  const borderBox = createBorderRectWithLineWidth(width, height, linewidth, borderColor);

  const group = new THREE.Group();
  group.add(filledBox);
  group.add(borderBox);

  borderBox.position.set(0, height / 2, 10);
  filledBox.position.set(0, -5, 1);


  return group;
}


export function getWidthOfText(textObj) {
  const box = new THREE.Box3().setFromObject(textObj);
  const size = new THREE.Vector3();
  box.getSize(size);
  debugLog("Text Width:", size.x);
  return size.x;
}

// Calculate scale based on window width
export function getResponsiveScale() {
  const width = window.innerWidth;
  if (width < 600) return 0.5; // Mobile
  if (width < 1200) return 0.8; // Tablet
  return 1.0; // Desktop
}

export function clearGroup(group) {
  // Loop backwards to avoid index shifting issues
  for (let i = group.children.length - 1; i >= 0; i--) {
    const mesh = group.children[i];
    group.remove(mesh);
    // The mesh still exists in your Map, but is gone from the 3D scene
  }
}

export function getDeviceType(width = window.innerWidth, height = window.innerHeight) {

  let aspectRatio = width / height;
  aspectRatio = Number(aspectRatio.toFixed(2));

  if (aspectRatio > 2) // landscape tall
    return 1; // ' mobile = landscape  ' + aspectRatio;
  else if (aspectRatio >= 1) // landscape pc , i pad
    return 2; // ' pc/tab = landscape  ' + aspectRatio;
  else if (aspectRatio < 0.5) // tall portrait 
    return 3; // ' mobile = portrait  ' + aspectRatio;
  else // portrait
    return 4; //' tab = portrait  ' + aspectRatio;
}

