import * as THREE from 'three';
import { Text, getSelectionRects } from 'troika-three-text'

import gsap from "gsap"
import { debugLog } from "../debugger/debugLog.js";

/**
 * @param {import("./sectionalAnimationManager.js").SectionalAnimationManager} animManager
 */
export default async function bookendSections(animManager) {

    debugLog("Section 1", "sec1_debug");

    const sectionDuration = 10;
    const butterflyPath = "paths/butterflySec1.json";
    const snakePath = "paths/snakeSec1.json";

    animManager.bookendSectionBeginTl = gsap.timeline({ paused: true });
    animManager.bookendSectionEndTl = gsap.timeline({ paused: true });

    animManager.bookendSectionBeginTl.call(animManager.contactCardManager.animateOutFloatingButton.bind(animManager.contactCardManager), [], 0)
        .call(() => document.body.style.cursor = "progress", [], 0);

    animManager.bookendSectionEndTl.call(animManager.contactCardManager.animateInFloatingButton.bind(animManager.contactCardManager), [], 0)
        .call(() => document.body.style.cursor = "pointer", [], 0);
    // return "test";
    debugLog("Book End Section  end ", "bookend_debug");

}