import { debugLog } from "../debugger/debugLog.js";

// utils/performance.js
export function getDeviceTier() {
    // 1. Check if mobile via User Agent (Fastest initial check)
    const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
    debugLog("Device Check: isMobile" + isMobile, "ppm,dc");

    // 2. Check hardware concurrency (CPU cores)
    const cores = navigator.hardwareConcurrency || 2;
    debugLog("Device Check: cores" + cores, "ppm,dc");

    // 3. Determine Tier
    if (isMobile || cores <= 4) {
        return 'LOW'; // Prioritize battery and steady framerate over effects
    } else if (cores <= 8) {
        return 'MEDIUM'; // Add basic polish (SMAA, slight grain)
    } else {
        return 'HIGH'; // Full cinematic pipeline
    }
}