import * as THREE from 'three';
import { Text, getSelectionRects } from 'troika-three-text'

import gsap from "gsap"
import { debugLog } from "../../../debugger/debugLog.js";
import { COLORS } from '../../../siteData.js';

export default async function section3Back(animManager) {

    debugLog("Section 3", "sec3_debug");

    animManager.section3BackTl = gsap.timeline({ paused: animManager.typeSectional })

    const sectionDuration = 5;
    const butterflyPath = "paths/butterflySec3.json";
    const snakePath = "paths/snakeSec3_2.json";

    const phasingData = { progress: 0 };

    // moon 
    animManager.section3BackTl
        .to(phasingData, {
            progress: sectionDuration, // Animate from 0 to 1
            duration: sectionDuration,
            // ease: "power1.inOut",
            onUpdate: () => {
                animManager.moonMaterial.uniforms.uTime.value = animManager.moonPhasingData.progress - phasingData.progress; // One full rotation for the phase cycle            
            },
            onComplete: () => {
                debugLog("moon completed section 3 ", "sec3_debug");
                animManager.moonPhasingData.progress = animManager.moonPhasingData.progress - phasingData.progress;
            }
        });

    animManager.section3BackTl.call(() => {
        debugLog("morph to snake", "tl_rev");
        animManager.snake.toggleMorph({
            duration: 1.5,
            ease: "power1.out",
        });
    }, [], 0);

    // animManager.section3BackTl.call(() => {
    //     animManager.toggleGrass();
    // },[], 0);

    animManager.section3BackTl.to(animManager.grassMesh.grassUniforms.opacity, {
        value: 1.2, duration: 1, ease: "none",
        onStart: () => {
            animManager.growGrass();
            animManager.grassMesh.mesh.visible = true;
            animManager.animateGrass = true;
        }
    }, 0);
    animManager.section3BackTl.to(animManager.fog1.cloud.material, {
        opacity: 0.1, duration: 1.0,
        onStart: () => {
            animManager.fog1.cloud.visible = true;
            animManager.fog2.visible = true;
            animManager.renderFog = true;
        }
    }, 1);

    animManager.section3BackTl.to(animManager.aboutTitleUniforms.uDissolve, {
        value: 0, duration: 2.5, ease: "none",
        onStart: () => {
            debugLog("showing nav items", "about_nav_bug2");
            animManager.aboutNavItems.forEach((buttonObj, index) => {
                buttonObj.text.layers.set(0);

            });
        },
    }, 0);

    animManager.section3BackTl.to(animManager.backgroundMesh.material, {
        opacity: 0,
        duration: 2,
        ease: "power2.inOut"
    }, 0);

    const targetTextColor = new THREE.Color(COLORS.midnight);
    animManager.section3BackTl.to(animManager.scene.background, {
        r: targetTextColor.r,
        g: targetTextColor.g,
        b: targetTextColor.b,
        duration: 2,
        ease: "power2.inOut"
    }, 0)
        .to(animManager.backdrop.material.uniforms.uOpacity, {
            value: 1.1,         // Target fully visible
            duration: 2,        // Over 3 seconds
            ease: "bounce.out(1.5)",
            onStart: () => {
                animManager.backdrop.visible = true;
                animManager.animateBackdrop = true;
            }
        }, ">+=1");


    animManager.section3BackTl.to(animManager.aboutUnderline.material, {
        linewidth: 1, duration: 2.5, ease: "expo.inOut",
        onUpdate: () => {
            animManager.aboutUnderline.material.needsUpdate = true;
        },
    }, 0);

    animManager.section3BackTl.to(animManager.workGroup.position, { y: animManager.workGroupStartPosY, duration: 2, ease: 'power2.inOut' }, 0);
    animManager.section3BackTl.to(animManager.testimonialGroup.position, { y: animManager.testimonialStartPosY, duration: 2, ease: 'power2.inOut' }, 0);

    if (animManager.aboutComicTheater) {
        const theaterMesh = animManager.aboutComicTheater;
        const theaterWidth = (theaterMesh.geometry?.parameters?.width || 1280) * theaterMesh.scale.x;
        const rightEdge = animManager.rightEdge ?? (animManager.visibleWidth / 2);
        const offscreenRightX = rightEdge + (theaterWidth / 2 + 100);

        theaterMesh.position.x = offscreenRightX;

        animManager.section3BackTl.fromTo(theaterMesh.position,
            { x: offscreenRightX },
            {
                x: 0,
                duration: 1.5,
                ease: "back.out(1.1)",
                onComplete: () => {
                    debugLog("Reversing comic page animation", "tl_rev");
                    animManager.setAboutContent(1, true);
                },
            }, 0);
        animManager.section3BackTl.to(animManager.aboutComicBase.material, { opacity: 1.0, duration: 1, ease: "none" }, 1.2);
    }


    const butterflyCurveId = await animManager.curveEditor.loadCurveFromPath(butterflyPath, "bfly-sec3-bck");
    const butterflyCurve1 = animManager.curveEditor.curves[butterflyCurveId].curve3;

    const butterflyFlightData = { progress: 1 };
    animManager.section3BackTl.to(butterflyFlightData, {
        progress: 0,
        duration: sectionDuration - 2,
        ease: "sine.in",
        // yoyo: true, // Go back and forth (optional)
        onUpdate: () => {
            if (butterflyFlightData.progress < 0)
                return;

            let position = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress, 0, 0);

            animManager.butterfly.position.copy(position);
            if (butterflyFlightData.progress + 0.01 < 1) {
                let lookAtPosition = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress + 0.01, 0, 0);
                animManager.butterfly.lookAt(lookAtPosition);
            }
            // const snakePos = position.add(animManager.bgMeshOffest);
            // animManager.snake.update(snakePos, butterflyFlightData.progress);

        }
    }, 1)
        .call(() => {
            animManager.flickerComicPanelsOn();
        }, [], ">0.5")
        .to(animManager.grassMesh.grassMaterial.uniforms.uColorIntensities.value, {
            [0]: 0.6,
            duration: 3,
            ease: "power2.out",
            onStart: () => {
                debugLog("grass2 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
            },
        }, ">")

        .to(animManager.grassMesh.grassMaterial.uniforms.uColorRadii.value, {
            [0]: 2000.0, // Your target full size
            duration: 3,
            ease: "back.out(1.2)",
            onStart: () => {
                debugLog("grass3 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
            },
        }, "<");


    const snakeCurveId = await animManager.curveEditor.loadCurveFromPath(snakePath, "snk-sec3-bck");
    const snakeCurve1 = animManager.curveEditor.curves[snakeCurveId].curve3;

    const snakeMotionData = { progress: 1 };
    animManager.section3BackTl.to(snakeMotionData, {
        progress: 0, // Animate from 0 to 1
        duration: sectionDuration - 1,
        ease: "power1.out",
        onUpdate: () => {
            if (snakeMotionData.progress < 0)
                return;
            let position = animManager.getResponsivePoint(snakeCurve1, snakeMotionData.progress, 0, animManager.bgMeshOffest.y);
            animManager.snake.update(position, snakeMotionData.progress);
        },

    }, 1);


    debugLog("Section 3 end", "sec3_debug");
    // return tl;
}