const LOG_FILTERS = ["lc_resize"];//,"text_cc","cc","mainl","cc_hover"];//"loading_c","ppm","sec2_debug","nw"];//["work_section","updateBGMeshSize", "mouse_event"];
const LOG_GLOBAL = ["error", "warn"];
function debugLog(message, filters = "") {

  if (typeof filters !== 'string')
    return;

  if (LOG_FILTERS.length > 0) {
    const providedFilters = filters.split(',').map(f => f.trim());



    if (!providedFilters.some(f => LOG_FILTERS.includes(f))) {
      if (!providedFilters.some(f => LOG_GLOBAL.includes(f))) {
        return;
      }
    }
    console.log("[DEBUG]: " + message + ", filter: " + filters);
  }

}

export { debugLog };