import * as THREE from 'three';
import { Text, getSelectionRects } from 'troika-three-text'

import gsap from "gsap"
import { debugLog } from "../../../debugger/debugLog.js";
import { COLORS } from '../../../siteData.js';

export default async function section2Back(animManager) {

    debugLog("Section 2", "sec2_debug");
    const sectionDuration = 5;
    const butterflyPath = "paths/butterflySec2_1.json";
    const snakePath = "paths/snakeSec2_bck.json";

    animManager.section2BackTl = gsap.timeline({ paused: animManager.typeSectional })
    const phasingData = { progress: 0 };

    animManager.section2BackTl
        .to(phasingData, {
            progress: sectionDuration, // Animate from 0 to 1
            duration: sectionDuration,
            onStart: () => {
                animManager.autoCloudSway = false;
            },
            onUpdate: () => {
                animManager.moonMaterial.uniforms.uTime.value = animManager.moonPhasingData.progress - phasingData.progress; // One full rotation for the phase cycle            
            },
            onComplete: () => {
                debugLog("moon completed section 2 ", "sec2_debug");
                animManager.moonPhasingData.progress = animManager.moonPhasingData.progress - phasingData.progress;
            }
        }, 0);
    animManager.section2BackTl.to(animManager.grassMesh.grassMaterial.uniforms.uColorIntensities.value, {
        [0]: 0.0,
        duration: 1,
        ease: "power2.out",
        onStart: () => {
            debugLog("grass2 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
        },
    }, 0)
        .to(animManager.grassMesh.grassMaterial.uniforms.uColorRadii.value, {
            [0]: 0.0, // Your target full size
            duration: 1,
            ease: "back.out(1.2)",
            onStart: () => {
                debugLog("grass3 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
            },
        }, "<")
        .to(animManager.backdrop.material.uniforms.uOpacity, {
            value: 0,         // Target fully visible
            duration: 1,        // Over 3 seconds
            ease: "power2.out",
            onComplete: () => {
                animManager.backdrop.visible = false;
                animManager.animateBackdrop = false;
            }
        }, "<");

    animManager.section2BackTl.to(animManager.fog1.cloud.material, {
        opacity: 0.0, duration: 1.0,
        onComplete: () => {
            animManager.fog1.cloud.visible = false;
            animManager.fog2.visible = false;
            animManager.renderFog = false;
        }
    }, 0);


    animManager.section2BackTl.to(animManager.quoteGroup.position, { y: animManager.quoteGroupStartPos.y, duration: 3, ease: 'power2.inOut' }, 0)
    animManager.section2BackTl.to(animManager.quoteGroup.position, { z: animManager.quoteGroupStartPos.z, duration: 2, ease: 'power1.in' }, 0)

        .to(animManager.quoteCloud.cloud.scale, {
            x: animManager.scaleFactor,
            y: animManager.scaleFactor,
            z: 1,
            duration: 1,
            ease: "back.out(1.5)"
        }, ">")
        .to(animManager.cloudDuplicate.scale, {
            x: animManager.scaleFactor,
            y: animManager.scaleFactor,
            z: 1,
            duration: 1,
            ease: "back.out(1.5)"
        }, "<")
        .to(animManager.quoteCloud.cloud.position, { x: 0, y: - Math.round(60 * animManager.scaleFactor), duration: 2, ease: "back.out(1.5)" }, "<")
        .to(animManager.cloudDuplicate.position, { x: 0, y: - Math.round(60 * animManager.scaleFactor), duration: 2, ease: "back.out(1.5)" }, "<")

        .to(animManager.quoteCloud.cloud.material.uniforms.threshold, { value: 0, duration: 1.0, ease: "power1.out" }, "<")
        .to(animManager.quoteTextEnglish.material, { opacity: 1, duration: 1, ease: 'power1.inOut' }, ">");

    const targetBgColor = new THREE.Color(COLORS.background);
    animManager.section2BackTl.to(animManager.scene.background, {
        r: targetBgColor.r,
        g: targetBgColor.g,
        b: targetBgColor.b,
        duration: 1,
        ease: "power2.inOut"
    }, 0);

    animManager.section2BackTl.to(animManager.backgroundMesh.material, {
        opacity: 1,
        duration: 1,
        ease: "power2.inOut"
    }, 0);

    animManager.section2BackTl.to(animManager.grassMesh.grassUniforms.opacity, {
        value: 0, duration: 1, ease: "none",
        onComplete: () => {
            animManager.disableGrass();
        }
    }, 0);

    animManager.section2BackTl.to(animManager.aboutComicBase.material, { opacity: 0.0, duration: 1, ease: "none" }, 0);

    if (animManager.aboutComicTheater) {
        const theaterMesh = animManager.aboutComicTheater;
        const theaterWidth = (theaterMesh.geometry?.parameters?.width || 1280) * theaterMesh.scale.x;
        const leftEdge = animManager.leftEdge ?? -(animManager.visibleWidth / 2);
        const offscreenLeftX = leftEdge - (theaterWidth / 2 + 100);

        theaterMesh.position.x = offscreenLeftX;

        const targetTextColor = new THREE.Color(COLORS.text);

        animManager.section2BackTl.fromTo(theaterMesh.position,
            { x: 0 },
            {
                x: offscreenLeftX,
                duration: 2.5,
                ease: "back.out(1.1)",
                onStart: () => {
                    theaterMesh.visible = false;

                },
            }, 1);
        animManager.section2BackTl.to(animManager.aboutTitleUniforms.uTextColor.value, {
            r: targetTextColor.r,
            g: targetTextColor.g,
            b: targetTextColor.b,
            duration: 0.8,
            ease: "bounce.out(1.5)"
        }, 0)
            // .to(animManager.aboutNavItems[0].text.material.color, {
            //     r: targetTextColor.r,
            //     g: targetTextColor.g,
            //     b: targetTextColor.b,
            //     duration: 0.8,
            //     ease: "bounce.out(1.5)"
            // }, "<")
            // .to(animManager.aboutNavItems[1].text.material.color, {
            //     r: targetTextColor.r,
            //     g: targetTextColor.g,
            //     b: targetTextColor.b,
            //     duration: 0.8,
            //     ease: "bounce.out(1.5)"
            // }, "<")
            // .to(animManager.aboutNavItems[2].text.material.color, {
            //     r: targetTextColor.r,
            //     g: targetTextColor.g,
            //     b: targetTextColor.b,
            //     duration: 0.8,
            //     ease: "bounce.out(1.5)"
            // }, "<")
            .to(animManager.aboutNavItems[0].underline.material.color, {
                r: targetTextColor.r,
                g: targetTextColor.g,
                b: targetTextColor.b,
                duration: 0.8,
                ease: "bounce.out(1.5)"
            }, "<")
            .to(animManager.aboutNavItems[1].underline.material.color, {
                r: targetTextColor.r,
                g: targetTextColor.g,
                b: targetTextColor.b,
                duration: 0.8,
                ease: "bounce.out(1.5)"
            }, "<")
            .to(animManager.aboutNavItems[2].underline.material.color, {
                r: targetTextColor.r,
                g: targetTextColor.g,
                b: targetTextColor.b,
                duration: 0.8,
                ease: "bounce.out(1.5)"
            }, "<")
            .to(animManager.aboutNavLeft.scale, {
                x: 0,
                y: 0,
                z: 0,
                duration: 0.8,
                ease: "back.in(1.5)"
            }, "<")
            .to(animManager.aboutNavRight.scale, {
                x: 0,
                y: 0,
                z: 0,
                duration: 0.4,
                ease: "back.in(1.5)"
            }, "<");
    }

    const snakeCurveId = await animManager.curveEditor.loadCurveFromPath(snakePath, "snk-sec2-bck");
    const snakeCurve1 = animManager.curveEditor.curves[snakeCurveId].curve3;

    const snakeMotionData = { progress: 1 };
    animManager.section2BackTl
        .call(() => {
            debugLog("movement phase completed ", "sec2_debug, morph");
            let position = animManager.getResponsivePoint(snakeCurve1, 1, 0, animManager.bgMeshOffest.y);
            position.y += 20;
            animManager.snake.toggleMorph({
                position: position, // Position on screen/world
                duration: 1.5,
                ease: "power1.out",
            });
            animManager.setAboutContent(0);
        }, [], 1)
        .to(snakeMotionData, {
            progress: 0, // Animate from 0 to 1
            duration: sectionDuration - 1,
            ease: "power1.out",
            onUpdate: () => {
                if (snakeMotionData.progress < 0)
                    return;
                let position = animManager.getResponsivePoint(snakeCurve1, snakeMotionData.progress, 0, animManager.bgMeshOffest.y);
                animManager.snake.update(position, snakeMotionData.progress);
            },

        }, 1.5),

        animManager.section2BackTl.to(animManager.aboutTextUniforms.uDissolve, { value: 0, duration: 2.5, ease: "none" }, 2)


    const butterflyCurveId = await animManager.curveEditor.loadCurveFromPath(butterflyPath, "bfly-sec2-bck");
    const butterflyCurve1 = animManager.curveEditor.curves[butterflyCurveId].curve3;

    const butterflyFlightData = { progress: 1 };
    animManager.section2BackTl.to(butterflyFlightData, {
        progress: 0,
        duration: sectionDuration,
        ease: "sine.in",
        onUpdate: () => {
            if (butterflyFlightData.progress < 0)
                return;

            let position = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress, 0, 0);
            animManager.butterfly.position.copy(position);
            if (butterflyFlightData.progress + 0.01 < 1) {
                let lookAtPosition = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress + 0.01, 0, 0);
                animManager.butterfly.lookAt(lookAtPosition);
            }
        },
    }, 2);




    debugLog("Section 2 end", "sec2_debug");
}