export async function sendClientQuery(formData, event) {
    let email = '';
    let message = '';

    if (formData && typeof formData === 'object') {
        email = formData.email ? String(formData.email).trim() : '';
        message = formData.message ? String(formData.message).trim() : '';
    } else if (typeof formData === 'string') {
        email = formData.trim();
        message = event && typeof event === 'string' ? event.trim() : '';
    }

    if (!email || !message) {
        const errorMsg = "Missing required fields: email and message are required.";
        debugLog("sendClientQuery failed: " + errorMsg, "contact");
        throw new Error(errorMsg);
    }

    debugLog("Form submit initiated", "contact");

    try {
        const docRef = await addDoc(collection(db, "clientMessages"), {
            email,
            message,
            createdAt: serverTimestamp()
        });

        debugLog("Form submitted successfully", "contact");
        return docRef;

    } catch (error) {
        console.error("Submission failed:", error);
        debugLog("Form Submission Failed " + error, "contact");
        throw error;

    } finally {
        debugLog("Form submitted", "contact");
    }
}
